  verify_session: {
    /** 要校验的 DSH 会话 id（必填）。 */
    sessionId: string;
  } & Record<string, JsonValue>;
  /** Activate the independent Vision Toolkit execution tools for this Agent after loading the vision-tools Skill. The Skill tool normally activates them automatically; call this once only after a direct Skill invocation when the visual tools are still absent. This activation tool disappears after success. */
  vision_toolkit_activate: Record<string, JsonValue>;
  /** 列出常用语音合成音色（edge-tts 微软神经语音，免费）。含普通话/方言/粤语/英/日/韩/法/德/俄/西。voice_tts 的 voice 参数也接受清单外的合法 edge 音色 id（如 zh-CN-XXXNeural）。 */
  voice_list: Record<string, JsonValue>;
  /** 语音转文字：调用 OpenAI 兼容 ASR 接口（默认 Groq whisper-large-v3-turbo；可切 openai/custom）。audio 为音频文件路径（mp3/wav/m4a/ogg/flac，≤25MB）；language/prompt 可选；output 可把转写文本写成 .txt。密钥用环境变量 DSH_VOICE_ASR_KEY 或配置 asrApiKey。 */
  voice_stt: {
    /** 音频文件路径（必填）。 */
