1	/**
2	 * dsh-wenyou — QQ 文字<QQ_GROUP_NAME_001>（文游）群监测插件。
3	 *
4	 * 拆分模块：lib/core.js（状态/子进程/密钥/解密/核心操作）+ lib/format.js（格式化）+ 本文件（命令+工具注册）。
5	 *
6	 * 提供：
7	 *   - /wenyou          状态
8	 *   - /wenyou check    检查<QQ_GROUP_NAME_001>群自上次以来新增消息
9	 *   - /wenyou pull     增量导出 chatlog txt + jsonl 到当前工作区
10	 *   - /wenyou brief    先 pull，再把简报任务交给当前 AI 会话
11	 *   - /wenyou setup    查看/修改配置（qq、group、export_dir 等）
12	 *   - 模型工具: wenyou_status / wenyou_check / wenyou_pull / wenyou_brief / wenyou_status_all / wenyou_tail / wenyou_pull_all
13	 */
14	import { defineTool } from '@deepseek-ai/dsh-tools';
15	import { randomUUID } from 'node:crypto';
16	import path from 'node:path';
17	import { existsSync } from 'node:fs';
18	import {
19	  DEFAULT_GROUP,
20	  DEFAULT_MAX_MESSAGES,
21	  loadState,
22	  saveState,
23	  resolveConfig,
24	  resolveExportDir,
25	  ensureDecrypted,
26	  ensureKeyMap,
27	  doCheck,
28	  doPull,
29	  doPullAll,
30	  runTail,
31	  runPython,
32	  quickStats,
33	  monitoredGroups,
34	  groupCursor,
35	  setGroupCursor,
36	  walWarning,
37	  buildBriefPrompt,
38	  errorText,
39	  cstTime,
40	} from './core.js';
41	import {
42	  statusText,
43	  checkText,
44	  pullText,
45	  configText,
46	  groupsText,
47	  tailText,
48	  pullAllText,
49	  toolResult,
50	} from './format.js';
51	
52	const pathJoin = path.join;
53	
54	export const name = 'dsh-wenyou';
55	export const inject = ['subprocess', 'commands', 'tools'];
56	
57	/** ---------- 工具辅助 ---------- */
58	
59	function userTextMessage(text) {
60	  return {
61	    id: randomUUID(),
62	    role: 'user',
63	    content: [{ type: 'text', text }],
64	    source: { kind: 'user' },
65	  };
66	}
67	
68	export function apply(ctx) {
69	  /** 一次性准备好 state + 有效配置。 */
70	  async function prepare(agent) {
71	    const state = await loadState();
72	    const cfg = await resolveConfig(state, agent);
73	    return { state, cfg };
74	  }
75	
76	  async function runCheckTool(ctxLocal, args, exec) {
77	    const { state, cfg } = await prepare(exec.agent);
78	    const gid = args.group != null ? Number(args.group) : null;
79	    await ensureDecrypted(ctxLocal, state, cfg, !!args.force, exec.signal);
80	    const result = await doCheck(ctxLocal, state, cfg, cfg.maxMessages, exec.signal, gid);
81	    const wal = await walWarning(cfg);
82	    return toolResult(true, checkText(result, wal), {
83	      group: result.group,
84	      groupName: result.groupName,
85	      count: result.count,
86	      truncated: result.truncated,
87	      firstAt: result.firstAt,
88	      lastAt: result.lastAt,
89	      sample: result.sample || [],
90	    });
91	  }
92	
93	  async function runPullTool(ctxLocal, args, exec) {
94	    const { state, cfg } = await prepare(exec.agent);
95	    let maxRows = cfg.maxMessages;
96	    if (args.max_messages !== undefined && args.max_messages !== null) {
97	      const n = Number(args.max_messages);
98	      if (!Number.isFinite(n) || n < 1 || n > 200000) {
99	        return toolResult(false, 'max_messages 需在 1~200000 之间');
100	      }
101	      maxRows = Math.floor(n);
102	    }
103	    const gid = args.group != null ? Number(args.group) : null;
104	    await ensureDecrypted(ctxLocal, state, cfg, !!args.force, exec.signal);
105	    const result = await doPull(ctxLocal, state, cfg, maxRows, exec.signal, gid);
106	    const wal = await walWarning(cfg);
107	    return toolResult(true, pullText(result, wal), {
108	      group: result.group,
109	      groupName: result.groupName,
110	      count: result.count,
111	      truncated: result.truncated,
112	      firstAt: result.firstAt,
113	      lastAt: result.lastAt,
114	      outJsonl: result.outJsonl,
115	      outTxt: result.outTxt,
116	      sample: result.sample || [],
117	    });
118	  }
119	
120	  /** 导出新消息并把「生成简报」的任务交给当前 AI 会话（同 /wenyou brief 命令）。 */
121	  async function runBriefTool(ctxLocal, args, exec) {
122	    const { state, cfg } = await prepare(exec.agent);
123	    let maxRows = cfg.maxMessages;
124	    if (args.max_messages !== undefined && args.max_messages !== null) {
125	      const n = Number(args.max_messages);
126	      if (Number.isFinite(n) && n >= 1 && n <= 200000) maxRows = Math.floor(n);
127	    }
128	    const gid = args.group != null ? Number(args.group) : null;
129	    await ensureDecrypted(ctxLocal, state, cfg, !!args.force, exec.signal);
130	    const result = await doPull(ctxLocal, state, cfg, maxRows, exec.signal, gid);
131	    if (result.count === 0) {
132	      return toolResult(true, `暂无新消息（游标停在 ${state.cursor ? state.cursor.lastAt : '初始位置'}），没有需要简报的内容。`, { count: 0, group: result.group });
133	    }
134	    if (result.truncated) {
135	      return toolResult(false, `新增消息超过导出上限（${maxRows}），游标未推进；请增大 max_messages 后重试。`, { count: result.count, truncated: true });
136	    }
137	    const prompt = buildBriefPrompt(cfg, result);
138	    const followed = exec.agent && typeof exec.agent.followup === 'function';
139	    if (followed) exec.agent.followup(userTextMessage(prompt));
140	    return toolResult(true, `✅ 已导出 ${result.count} 条新消息（${result.firstAt} ～ ${result.lastAt}）${followed ? '并交给当前会话生成简报。' : '（未能投递简报任务，请自行读取文件总结）'}\n聊天记录：${result.outTxt}\n我会接着读文件、写增量总结并更新 qq_monitor_state.json。`, {
141	      group: result.group,
142	      groupName: result.groupName,
143	      count: result.count,
144	      firstAt: result.firstAt,
145	      lastAt: result.lastAt,
146	      outJsonl: result.outJsonl,
147	      outTxt: result.outTxt,
148	      followupDelivered: followed,
149	    });
150	  }
151	
152	  async function runStatusTool(_args, exec) {
153	    const { state, cfg } = await prepare(exec.agent);
154	    // 复用 quickStats 消除与命令中的重复
155	    let quick = null;
156	    try {
157	      if (existsSync(cfg.plainMsgDb)) {
158	        quick = await quickStats(ctx, cfg, state, exec.signal);
159	      }
160	    } catch {
161	      quick = null;
162	    }
163	    return toolResult(true, statusText(state, cfg, quick), {
164	      config: {
165	        qq: cfg.qq,
166	        group: cfg.group,
167	        dbDir: cfg.dbDir,
168	        exportDir: cfg.exportDir,
169	        plainMsgDb: cfg.plainMsgDb,
170	        maxMessages: cfg.maxMessages,
171	      },
172	      cursor: state.cursor,
173	      quickCount: quick ? quick.count : null,
174	    });
175	  }
176	
177	  async function runStatusAllTool(_args, exec) {
178	    const { state, cfg } = await prepare(exec.agent);
179	    const names = {};
180	    for (const { gid } of monitoredGroups(state)) {
181	      try {
182	        const nm = await runPython(ctx, ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(gid), '--since', '0', '--max', '1'], cfg.exportDir, exec.signal);
183	        names[gid] = nm.groupName;
184	      } catch { /* 名称仅作展示 */ }
185	    }
186	    const detail = monitoredGroups(state).map(({ gid }) => {
187	      const c = groupCursor(state, gid);
188	      return { group: gid, groupName: names[gid] || '', cursor: c ? { lastTs: c.lastTs, lastAt: c.lastAt } : null };
189	    });
190	    return toolResult(true, groupsText(state, names, groupCursor), { groups: detail });
191	  }
192	
193	  async function runTailTool(ctxLocal, args, exec) {
194	    const { state, cfg } = await prepare(exec.agent);
195	    const gid = Number(args.group);
196	    const n = Number(args.n);
197	    if (!Number.isFinite(gid) || !Number.isFinite(n) || n < 1) {
198	      return toolResult(false, 'group 与 n 参数必填：tail 最近 n 条以建立游标');
199	    }
200	    const names = {};
201	    try {
202	      const nm = await runPython(ctxLocal, ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(gid), '--since', '0', '--max', '1'], cfg.exportDir, exec.signal);
203	      names[gid] = nm.groupName;
204	    } catch { /* ignore */ }
205	    if ((cfg.group !== gid) && !(Array.isArray(cfg.extraGroups) && cfg.extraGroups.some((x) => Number(x && x.gid) === gid))) {
206	      state.config.extraGroups = state.config.extraGroups || [];
207	      state.config.extraGroups.push({ gid, name: names[gid] || '' });
208	    }
209	    await ensureDecrypted(ctxLocal, state, cfg, !!args.force, exec.signal);
210	    const outJsonl = pathJoin(cfg.exportDir, `msgs_尾巴_${gid}.jsonl`);
211	    const outTxt = pathJoin(cfg.exportDir, `chatlog_尾巴_${gid}.txt`);
212	    const result = await runTail(ctxLocal, cfg, gid, n, outJsonl, outTxt, exec.signal);
213	    if (result.count > 0 && result.lastTs != null) {
214	      await setGroupCursor(state, gid, { lastTs: result.lastTs, lastRowid: null, lastAt: result.lastAt });
215	    } else {
216	      await setGroupCursor(state, gid, { lastTs: Date.now() / 1000, lastRowid: null, lastAt: cstTime(Date.now()) });
217	    }
218	    return toolResult(true, tailText(result) + '\n游标已建立，之后 /wenyou pullall 会把该群并入合订。', {
219	      group: result.group, groupName: result.groupName, count: result.count,
220	      lastTs: result.lastTs, lastAt: result.lastAt, outTxt: result.outTxt, outJsonl: result.outJsonl,
221	    });
222	  }
223	
224	  async function runPullAllTool(ctxLocal, args, exec) {
225	    const { state, cfg } = await prepare(exec.agent);
226	    let maxRows = cfg.maxMessages;
227	    if (args.max_messages !== undefined && args.max_messages !== null) {
228	      const n = Number(args.max_messages);
229	      if (Number.isFinite(n) && n >= 1 && n <= 200000) maxRows = Math.floor(n);
230	    }
231	    await ensureDecrypted(ctxLocal, state, cfg, !!args.force, exec.signal);
232	    const result = await doPullAll(ctxLocal, state, cfg, maxRows, exec.signal);
233	    return toolResult(true, pullAllText(result), result);
234	  }
235	
236	  // ---------- /wenyou 命令 ----------
237	  ctx.commands.register({
238	    name: 'wenyou',
239	    description: 'QQ 文游群监测：状态 / check / pull / brief / setup / tail / groups / add / pullall',
240	    handler: async (invocation) => {
241	      try {
242	        const { state, cfg } = await prepare(invocation.agent);
243	        const parts = invocation.rawInput.trim().split(/\s+/).filter(Boolean);
244	        const aliases = {
245	          '状态': 'status',
246	          '检查': 'check',
247	          '导出': 'pull',
248	          '简报': 'brief',
249	          '设置': 'setup',
250	          '合订': 'pullall',
251	          '多群': 'pullall',
252	          '尾巴': 'tail',
253	          '群': 'groups',
254	          '加群': 'add',
255	          '列表': 'groups',
256	        };
257	        const head = aliases[parts[0]] || parts[0] || 'status';
258	
259	        if (head === 'status') {
260	          // 复用 quickStats 消除重复
261	          let quick = null;
262	          try {
263	            if (existsSync(cfg.plainMsgDb)) {
264	              quick = await quickStats(ctx, cfg, state, invocation.signal);
265	            }
266	          } catch {
267	            quick = null;
268	          }
269	          return { kind: 'success', text: statusText(state, cfg, quick) };
270	        }
271	
272	        if (head === 'groups' || head === 'g') {
273	          // 查询若干群的名称（尽量显示名称，读不到也不阻塞）
274	          const names = {};
275	          try {
276	            for (const { gid } of monitoredGroups(state)) {
277	              const nm = await runPython(ctx, ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(gid), '--since', '0', '--max', '1'], cfg.exportDir, invocation.signal);
278	              names[gid] = nm.groupName;
279	            }
280	          } catch {
281	            /* 名称仅作展示，失败忽略 */
282	          }
283	          return { kind: 'success', text: groupsText(state, names, groupCursor) };
284	        }
285	
286	        if (head === 'add') {
287	          const gidStr = parts[1];
288	          const name = parts.slice(2).join(' ');
289	          const gid = Number(gidStr);
290	          if (!Number.isFinite(gid)) return { kind: 'error', text: '用法：/wenyou add <群号> [群名称]' };
291	          const existing = (state.config.extraGroups || []).filter((g) => Number(g && g.gid) === gid);
292	          if (existing.length) {
293	            return { kind: 'error', text: `群 ${gid} 已在监测列表中。` };
294	          }
295	          state.config.extraGroups = state.config.extraGroups || [];
296	          state.config.extraGroups.push({ gid, name: name || '' });
297	          await saveState(state);
298	          const refreshed = await resolveConfig(state, invocation.agent);
299	          const hint = groupCursor(state, gid)
300	            ? '（已有游标）'
301	            : ' → 请执行 /wenyou tail <群号> <条数> 建立游标后再使用。';
302	          return { kind: 'success', text: `✅ 已加入监测群 ${gid}${name ? `（${name}）` : ''}${hint}\n\n${groupsText(state, {}, groupCursor)}` };
303	        }
304	
305	        if (head === 'tail') {
306	          const gid = Number(parts[1]);
307	          const n = Number(parts[2]);
308	          if (!Number.isFinite(gid) || !Number.isFinite(n) || n < 1) {
309	            return { kind: 'error', text: '用法：/wenyou tail <群号> <条数（如 500）>' };
310	          }
311	          // 不在监测列表就先加入
312	          const names = {};
313	          try {
314	            const nm = await runPython(ctx, ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(gid), '--since', '0', '--max', '1'], cfg.exportDir, invocation.signal);
315	            names[gid] = nm.groupName;
316	          } catch { /* ignore */ }
317	          if ((cfg.group !== gid) && !(Array.isArray(cfg.extraGroups) && cfg.extraGroups.some((x) => Number(x && x.gid) === gid))) {
318	            state.config.extraGroups = state.config.extraGroups || [];
319	            state.config.extraGroups.push({ gid, name: names[gid] || '' });
320	          }
321	          await ensureDecrypted(ctx, state, cfg, false, invocation.signal);
322	          const outJsonl = pathJoin(cfg.exportDir, `msgs_尾巴_${gid}.jsonl`);
323	          const outTxt = pathJoin(cfg.exportDir, `chatlog_尾巴_${gid}.txt`);
324	          const result = await runTail(ctx, cfg, gid, n, outJsonl, outTxt, invocation.signal);
325	          // 以尾部最新时间戳作为游标：之后的 pull/pullall 才能拿到更新。
326	          if (result.count > 0 && result.lastTs != null) {
327	            await setGroupCursor(state, gid, { lastTs: result.lastTs, lastRowid: null, lastAt: result.lastAt });
328	          } else {
329	            await setGroupCursor(state, gid, { lastTs: Date.now() / 1000, lastRowid: null, lastAt: cstTime(Date.now()) });
330	          }
331	          return { kind: 'success', text: tailText(result) + '\n游标已建立。之后 /wenyou pullall 会把该群并入合订。' };
332	        }
333	
334	        if (head === 'pullall' || head === 'pa') {
335	          await ensureDecrypted(ctx, state, cfg, false, invocation.signal);
336	          const result = await doPullAll(ctx, state, cfg, cfg.maxMessages, invocation.signal);
337	          return { kind: 'success', text: pullAllText(result) };
338	        }
339	
340	        if (head === 'check') {
341	          await ensureDecrypted(ctx, state, cfg, false, invocation.signal);
342	          const gid = parts[1] ? Number(parts[1]) : null;
343	          const result = await doCheck(ctx, state, cfg, cfg.maxMessages, invocation.signal, gid);
344	          const wal = await walWarning(cfg);
345	          return { kind: 'success', text: checkText(result, wal) };
346	        }
347	
348	        if (head === 'pull') {
349	          await ensureDecrypted(ctx, state, cfg, false, invocation.signal);
350	          const gid = parts[1] ? Number(parts[1]) : null;
351	          const result = await doPull(ctx, state, cfg, cfg.maxMessages, invocation.signal, gid);
352	          const wal = await walWarning(cfg);
353	          return { kind: 'success', text: pullText(result, wal) };
354	        }
355	
356	        if (head === 'brief') {
357	          await ensureDecrypted(ctx, state, cfg, false, invocation.signal);
358	          const result = await doPull(ctx, state, cfg, cfg.maxMessages, invocation.signal);
359	          if (result.count === 0) {
360	            return { kind: 'success', text: `暂无新消息（游标停在 ${state.cursor ? state.cursor.lastAt : '初始位置'}），没有需要简报的内容。` };
361	          }
362	          if (result.truncated) {
363	            return { kind: 'error', text: `新增消息超过导出上限（${cfg.maxMessages}），游标未推进；请 /wenyou setup max_messages 调大后重试。` };
364	          }
365	          const prompt = buildBriefPrompt(cfg, result);
366	          invocation.agent.followup(userTextMessage(prompt));
367	          return {
368	            kind: 'success',
