1	/**
2	 * dsh-wenyou 核心逻辑模块：状态管理、子进程、密钥/解密、导入导出。
3	 * 从 index.js 拆分而来，保持内部 API 兼容。
4	 */
5	import { promises as fsp } from 'node:fs';
6	import { existsSync } from 'node:fs';
7	import os from 'node:os';
8	import path from 'node:path';
9	import { fileURLToPath } from 'node:url';
10	
11	const HERE = path.dirname(fileURLToPath(import.meta.url));
12	const PLUGIN_ROOT = path.resolve(HERE, '..');
13	const ASSETS = path.join(PLUGIN_ROOT, 'assets');
14	export const QQ_DECRYPT_CJS = path.join(ASSETS, 'qq_decrypt.cjs');
15	export const QQ_DUMP_EXE = path.join(ASSETS, 'qq_dump_db.exe');
16	export const WENYOU_READ_PY = path.join(ASSETS, 'wenyou_read.py');
17	
18	export const DSH_HOME = process.env.DSH_HOME || path.join(os.homedir(), '.dsh');
19	export const DATA_DIR = path.join(DSH_HOME, 'storages', 'dsh-wenyou');
20	export const STATE_FILE = path.join(DATA_DIR, 'state.json');
21	
22	export const DEFAULT_QQ = '<QQ_ACCOUNT_001>';
23	export const DEFAULT_GROUP = <QQ_GROUP_001>;
24	export const DEFAULT_MAX_MESSAGES = 20000;
25	// 可从环境变量覆盖的 fallback workspace（跨机器不写死）
26	export const FALLBACK_WORKSPACE = process.env.WENYOU_FALLBACK_WORKSPACE
27	  || path.join(os.homedir(), 'Downloads', 'deepseek-harness', '温蒂尼局势');
28	
29	export function pad(n) {
30	  return String(n).padStart(2, '0');
31	}
32	
33	/** 把毫秒时间戳格式化成 CST 可读串（不用 Date 的本地时区假设）。 */
34	export function cstTime(ms) {
35	  const d = new Date(ms + 8 * 3600 * 1000);
36	  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`;
37	}
38	
39	export function cstTimeFull(ms) {
40	  const d = new Date(ms + 8 * 3600 * 1000);
41	  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
42	}
43	
44	export function errorText(err) {
45	  return String(err && err.message ? err.message : err);
46	}
47	
48	export async function writeJsonAtomic(file, value) {
49	  const tmp = `${file}.tmp`;
50	  await fsp.writeFile(tmp, JSON.stringify(value, null, 2), 'utf8');
51	  try {
52	    await fsp.rename(tmp, file);
53	  } catch {
54	    await fsp.rm(file, { force: true });
55	    await fsp.rename(tmp, file);
56	  }
57	}
58	
59	export async function readJson(file, fallback) {
60	  try {
61	    return JSON.parse(await fsp.readFile(file, 'utf8'));
62	  } catch {
63	    return fallback;
64	  }
65	}
66	
67	export function defaults() {
68	  return {
69	    version: 1,
70	    config: {
71	      qq: DEFAULT_QQ,
72	      group: DEFAULT_GROUP,
73	      dbDir: '',
74	      exportDir: '',
75	      keyMapPath: '',
76	      plainMsgDb: '',
77	      plainGroupDb: '',
78	      maxMessages: DEFAULT_MAX_MESSAGES,
79	      extraGroups: [],   // 额外监测群：[{ gid: <number>, name: '' }, ...]
80	      topic: '',         // 文游主题名（用于简报与增量文件命名；空=用默认「群岛」）
81	      briefBase: '',     // 基线总结文件名（空=自动生成 <topic>外交局势总结.md）
82	      briefPrefix: '',   // 增量总结文件前缀（空=自动生成 <topic>局势总结_增量_）
83	    },
84	    cursor: null,
85	    groups: {},          // 每个群的独立游标：{ <gid>: { lastTs, lastRowid, lastAt } }
86	    lastDecrypt: {},
87	    lastCheck: null,
88	  };
89	}
90	
91	export function mergeState(raw) {
92	  const base = defaults();
93	  if (!raw || typeof raw !== 'object') return base;
94	  base.config = { ...base.config, ...(raw.config || {}) };
95	  base.config.extraGroups = Array.isArray(base.config.extraGroups) ? base.config.extraGroups : [];
96	  base.cursor = raw.cursor && typeof raw.cursor === 'object' ? { ...raw.cursor } : null;
97	  base.groups = raw.groups && typeof raw.groups === 'object' ? raw.groups : {};
98	  base.lastDecrypt = raw.lastDecrypt && typeof raw.lastDecrypt === 'object' ? raw.lastDecrypt : {};
99	  base.lastCheck = raw.lastCheck || null;
100	  return base;
101	}
102	
103	/** 全部受监测群（含主群在内）：返回 [{gid, name}]。 */
104	export function monitoredGroups(state) {
105	  const main = Number(state.config.group) || DEFAULT_GROUP;
106	  const out = [{ gid: main, name: '' }];
107	  for (const g of (state.config.extraGroups || [])) {
108	    const gid = Number(g && g.gid);
109	    if (Number.isFinite(gid) && gid !== main) out.push({ gid, name: (g && g.name) || '' });
110	  }
111	  return out;
112	}
113	
114	/** 取某群的游标：主群用 state.cursor，其它群用 state.groups[gid]。 */
115	export function groupCursor(state, gid) {
116	  gid = Number(gid);
117	  const main = Number(state.config.group) || DEFAULT_GROUP;
118	  if (gid === main) {
119	    return state.cursor && Number.isFinite(Number(state.cursor.lastTs)) ? state.cursor : null;
120	  }
121	  const g = state.groups && state.groups[gid];
122	  return g && Number.isFinite(Number(g.lastTs)) ? g : null;
123	}
124	
125	/** 写某群的游标。 */
126	export async function setGroupCursor(state, gid, cursor) {
127	  gid = Number(gid);
128	  const main = Number(state.config.group) || DEFAULT_GROUP;
129	  if (gid === main) {
130	    state.cursor = { ...cursor };
131	  } else {
132	    state.groups = state.groups || {};
133	    state.groups[gid] = { ...cursor };
134	  }
135	  await saveState(state);
136	}
137	
138	export async function loadState() {
139	  const raw = await readJson(STATE_FILE, null);
140	  return mergeState(raw);
141	}
142	
143	export async function saveState(state) {
144	  await fsp.mkdir(DATA_DIR, { recursive: true });
145	  await writeJsonAtomic(STATE_FILE, state);
146	}
147	
148	export function sessionCwd(agent) {
149	  try {
150	    const cwd = agent && agent.session && agent.session.header && agent.session.header.cwd;
151	    return cwd || '';
152	  } catch {
153	    return '';
154	  }
155	}
156	
157	/** 从工作区 qq_monitor_state.json 继承旧流程游标，保证“不漏也不重”。 */
158	export async function seedFromWorkspace(state, exportDir) {
159	  const qms = await readJson(path.join(exportDir, 'qq_monitor_state.json'), null);
160	  if (!qms) return false;
161	  // 只有用户未显式改过群号时才沿用旧工作区状态，避免 setup 被覆盖。
162	  if (qms.trigger_group && state.config.group === DEFAULT_GROUP) state.config.group = qms.trigger_group;
163	  if (typeof qms.threshold === 'number') state.config.threshold = qms.threshold;
164	  if (!state.cursor && typeof qms.last_reported_ts === 'number') {
165	    state.cursor = {
166	      lastTs: qms.last_reported_ts,
167	      lastRowid: typeof qms.last_reported_rowid === 'number' ? qms.last_reported_rowid : null,
168	      lastAt: qms.last_reported_at_cst || '',
169	    };
170	  }
171	  return true;
172	}
173	
174	export async function resolveExportDir(agent, state) {
175	  if (state.config.exportDir) return state.config.exportDir;
176	  const cwd = sessionCwd(agent);
177	  if (cwd) return cwd;
178	  if (existsSync(FALLBACK_WORKSPACE)) return FALLBACK_WORKSPACE;
179	  return FALLBACK_WORKSPACE;
180	}
181	
182	export async function resolveConfig(state, agent) {
183	  const exportDir = await resolveExportDir(agent, state);
184	  // 旧流程的状态文件可能在当前工作区，也可能在“温蒂尼局势”跟踪工作区，两处都试。
185	  const seen = new Set();
186	  for (const dir of [exportDir, FALLBACK_WORKSPACE]) {
187	    if (!dir || seen.has(dir)) continue;
188	    seen.add(dir);
189	    await seedFromWorkspace(state, dir);
190	  }
191	  const cfg = state.config;
192	  const qq = cfg.qq || DEFAULT_QQ;
193	  const dbDir = cfg.dbDir || path.join(os.homedir(), 'Documents', 'Tencent Files', qq, 'nt_qq', 'nt_db');
194	  let plainMsgDb = cfg.plainMsgDb;
195	  if (!plainMsgDb) {
196	    const live = path.join(exportDir, 'nt_msg_live_plain.db');
197	    plainMsgDb = existsSync(live) ? live : path.join(DATA_DIR, 'plain', 'nt_msg_plain.db');
198	  }
199	  let plainGroupDb = cfg.plainGroupDb;
200	  if (!plainGroupDb) {
201	    const existing = path.join(exportDir, 'group_info_plain.db');
202	    plainGroupDb = existsSync(existing) ? existing : path.join(DATA_DIR, 'plain', 'group_info_plain.db');
203	  }
204	  return {
205	    exportDir,
206	    qq,
207	    group: cfg.group,
208	    dbDir,
209	    keyMapPath: cfg.keyMapPath,
210	    plainMsgDb,
211	    plainGroupDb,
212	    maxMessages: Number(cfg.maxMessages) > 0 ? Number(cfg.maxMessages) : DEFAULT_MAX_MESSAGES,
213	    topic: String(cfg.topic || '').trim(),
214	    briefBase: String(cfg.briefBase || '').trim(),
215	    briefPrefix: String(cfg.briefPrefix || '').trim(),
216	  };
217	}
218	
219	/** ---------- 子进程 ---------- */
220	
221	export async function runProcess(ctx, argv, cwd, signal) {
222	  const proc = ctx.subprocess.spawn({
223	    argv,
224	    cwd,
225	    graceMs: 5000,
226	    signal,
227	    stdio: {
228	      stdin: 'ignore',
229	      stdout: { maxBytes: 1 << 16, spill: { maxBytes: 1 << 22 } },
230	      stderr: { maxBytes: 1 << 16, spill: { maxBytes: 1 << 22 } },
231	    },
232	  });
233	  const outcome = await proc.done;
234	  const out = proc.collected.stdout?.readFrom(0).text ?? '';
235	  const err = proc.collected.stderr?.readFrom(0).text ?? '';
236	  if (outcome.exitCode !== 0) {
237	    throw new Error(`命令失败 exit=${outcome.exitCode}: ${err || out}`);
238	  }
239	  return { out, err };
240	}
241	
242	export async function findPython(ctx, signal) {
243	  const candidates = [
244	    process.env.WENYOU_PYTHON,
245	    path.join(os.homedir(), '.cache', 'codex-runtimes', 'codex-primary-runtime', 'dependencies', 'python', 'python.exe'),
246	    'python',
247	    'py',
248	  ].filter(Boolean);
249	  for (const candidate of candidates) {
250	    try {
251	      return await ctx.subprocess.resolveExecutable(candidate, undefined, signal);
252	    } catch {
253	      // 尝试下一个
254	    }
255	  }
256	  throw new Error('未找到 Python：请安装 Python 3 或用 /wenyou setup 指定环境变量 WENYOU_PYTHON 指向 python.exe');
257	}
258	
259	export async function runPython(ctx, args, cwd, signal) {
260	  const python = await findPython(ctx, signal);
261	  const { out } = await runProcess(ctx, [python, WENYOU_READ_PY, ...args], cwd, signal);
262	  const lines = out.trim().split(/\r?\n/);
263	  const lastLine = lines[lines.length - 1] || '';
264	  if (!lastLine.startsWith('__RESULT__')) {
265	    throw new Error(`wenyou_read.py 未返回结果：${out.slice(-400)}`);
266	  }
267	  return JSON.parse(lastLine.slice('__RESULT__'.length));
268	}
269	
270	/** 导出某群最近 n 条消息（time 升序），用于初次建立游标 / 回看尾巴。 */
271	export async function runTail(ctx, cfg, group, n, outJsonl, outTxt, signal) {
272	  return runPython(
273	    ctx,
274	    ['tail', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(group), '--n', String(n), '--out-jsonl', outJsonl, '--out-txt', outTxt],
275	    cfg.exportDir,
276	    signal,
277	  );
278	}
279	
280	/** ---------- 密钥 ---------- */
281	
282	export async function ensureKeyMap(ctx, cfg, signal) {
283	  // 扫描候选：用户配置 > 环境变量 > 已知默认位置 > 插件数据目录
284	  const candidates = [
285	    cfg.keyMapPath,
286	    process.env.WENYOU_KEY_MAP,
287	    path.join(os.homedir(), '.codex', 'skills', 'qq-chat-reader', 'keys', 'key_map.json'),
288	    path.join(os.homedir(), 'Documents', 'Codex', '2026-08-04', 'qq-3', 'work', 'tools', 'qq_dump_db', 'output', String(cfg.qq), 'key_map.json'),
289	    path.join(DATA_DIR, 'key_map.json'),
290	  ].filter(Boolean);
291	  for (const candidate of candidates) {
292	    try {
293	      const st = await fsp.stat(candidate);
294	      if (st.isFile() && st.size > 0) return candidate;
295	    } catch {
296	      // 不存在，继续找
297	    }
298	  }
299	
300	  if (!existsSync(QQ_DUMP_EXE)) {
301	    throw new Error('未找到 key_map.json，且插件缺少 qq_dump_db.exe，无法提取密钥');
302	  }
303	  const target = path.join(DATA_DIR, 'key_map.json');
304	  await fsp.mkdir(DATA_DIR, { recursive: true });
305	  const proc = ctx.subprocess.spawn({
306	    argv: [QQ_DUMP_EXE, '--qq', String(cfg.qq), '--output', target],
307	    cwd: DATA_DIR,
308	    graceMs: 5000,
309	    signal,
310	    stdio: {
311	      stdin: 'ignore',
312	      stdout: { maxBytes: 4096, spill: { maxBytes: 1 << 18 } },
313	      stderr: { maxBytes: 4096, spill: { maxBytes: 1 << 18 } },
314	    },
315	  });
316	  try {
317	    // 等待 proc 完成（而非 busy-wait 轮询）
318	    const outcome = await Promise.race([
319	      proc.done,
320	      new Promise((_, reject) => setTimeout(() => reject(new Error('密钥提取超时：请确认 QQ 已登录且为 NTQQ 新版，然后重试')), <QQ_ACCOUNT_005>)),
321	    ]);
322	    if (outcome.exitCode !== 0) {
323	      const err = proc.collected.stderr?.readFrom(0).text ?? '';
324	      throw new Error(`密钥提取失败 exit=${outcome.exitCode}: ${err}`);
325	    }
326	    const st = await fsp.stat(target);
327	    if (st.isFile() && st.size > 0) return target;
328	    throw new Error('密钥提取失败：未生成 key_map.json');
329	  } finally {
330	    try {
331	      await proc.terminate();
332	    } catch {
333	      // 进程可能已自行退出
334	    }
335	  }
336	}
337	
338	/** ---------- 解密 ---------- */
339	
340	export async function ensureDecrypted(ctx, state, cfg, force, signal) {
341	  const keyMapPath = await ensureKeyMap(ctx, cfg, signal);
342	  const targets = [
343	    { key: 'msg', label: '消息库', src: path.join(cfg.dbDir, 'nt_msg.db'), out: cfg.plainMsgDb },
344	    { key: 'group', label: '群资料库', src: path.join(cfg.dbDir, 'group_info.db'), out: cfg.plainGroupDb },
345	  ];
346	  const report = [];
347	  for (const item of targets) {
348	    let srcStat;
349	    try {
350	      srcStat = await fsp.stat(item.src);
351	    } catch {
352	      throw new Error(`找不到 QQ ${item.label}：${item.src}（请确认 QQ 数据目录，或 /wenyou setup db_dir <目录>）`);
353	    }
354	    let outStat = null;
355	    try {
356	      outStat = await fsp.stat(item.out);
357	    } catch {
358	      outStat = null;
359	    }
360	    // 明文库是在源库之后（或同一时刻之后）生成的，就认为可用；比持久化的
361	    // mtime+size 更稳，因为源库可能在解密过程中被 QQ 又写入。
362	    const fresh = !force
363	      && outStat !== null
364	      && outStat.size > 0
365	      && outStat.mtimeMs >= srcStat.mtimeMs;
366	    if (fresh) {
367	      report.push({ ...item, skipped: true });
368	      continue;
369	    }
370	    await fsp.mkdir(path.dirname(item.out), { recursive: true });
371	    await runProcess(
372	      ctx,
373	      [process.execPath, QQ_DECRYPT_CJS, item.src, item.out, keyMapPath],
374	      ASSETS,
375	      signal,
376	    );
377	    state.lastDecrypt[item.key] = {
378	      src: item.src,
379	      mtimeMs: srcStat.mtimeMs,
380	      size: srcStat.size,
381	      at: cstTimeFull(Date.now()),
382	    };
383	    await saveState(state);
384	    report.push({ ...item, skipped: false });
385	  }
386	  return { keyMapPath, report };
387	}
388	
389	export async function walWarning(cfg) {
390	  const wal = path.join(cfg.dbDir, 'nt_msg.db-wal');
391	  try {
392	    const st = await fsp.stat(wal);
393	    if (st.size > 256 * 1024) {
394	      return `提示：QQ 的 WAL 暂存文件还有 ${(st.size / 1024 / 1024).toFixed(1)} MB 未归并，最新消息可能不在主库中；若新增数偏少，等一会再试或正常退出 QQ 后重试。`;
395	    }
396	  } catch {
397	    // 没有 WAL，无需提示
398	  }
399	  return '';
400	}
401	
402	/** ---------- 核心操作 ---------- */
403	
404	export function cursorSince(state) {
405	  if (state.cursor && Number.isFinite(Number(state.cursor.lastTs))) {
406	    return { since: Number(state.cursor.lastTs), fresh: true };
407	  }
408	  return { since: 0, fresh: false };
409	}
410	
411	/** 检查某群（默认主群）自其游标以来的新增消息。 */
412	export async function doCheck(ctx, state, cfg, maxRows, signal, group) {
413	  const gid = group == null ? Number(cfg.group) : Number(group);
414	  const cursor = groupCursor(state, gid);
415	  if (!cursor) {
416	    throw new Error(`群 ${gid} 游标尚未设置：请先对该群 /wenyou tail <gid> <n> 建立游标，或 /wenyou pull <gid>`);
417	  }
418	  const since = Number(cursor.lastTs);
419	  const sinceRowid = Number(cursor.lastRowid) || 0;
420	  const result = await runPython(
421	    ctx,
422	    ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(gid), '--since', String(since), '--since-rowid', String(sinceRowid), '--max', String(maxRows)],
423	    cfg.exportDir,
424	    signal,
425	  );
426	  state.lastCheck = { at: cstTimeFull(Date.now()), group: gid, count: result.count, truncated: !!result.truncated };
427	  await saveState(state);
428	  return result;
429	}
430	
431	/** 导出某群（默认主群）自其游标以来的新消息并推进该群游标。 */
432	export async function doPull(ctx, state, cfg, maxRows, signal, group) {
433	  const gid = group == null ? Number(cfg.group) : Number(group);
434	  const cursor = groupCursor(state, gid);
435	  if (!cursor) {
436	    throw new Error(`群 ${gid} 游标尚未设置：请先对该群 /wenyou tail <gid> <n> 建立游标，或 /wenyou pull <gid>`);
437	  }
438	  const since = Number(cursor.lastTs);
439	  const sinceRowid = Number(cursor.lastRowid) || 0;
440	  const outJsonl = path.join(cfg.exportDir, `msgs_增量_${gid}.jsonl`);
441	  const outTxt = path.join(cfg.exportDir, `chatlog_增量_${gid}.txt`);
442	  const result = await runPython(
443	    ctx,
444	    [
445	      'pull',
446	      '--db', cfg.plainMsgDb,
447	      '--group-db', cfg.plainGroupDb,
448	      '--group', String(gid),
449	      '--since', String(since),
450	      '--since-rowid', String(sinceRowid),
451	      '--out-jsonl', outJsonl,
452	      '--out-txt', outTxt,
453	      '--max', String(maxRows),
454	    ],
455	    cfg.exportDir,
456	    signal,
457	  );
458	  if (result.count > 0 && !result.truncated) {
459	    await setGroupCursor(state, gid, { lastTs: result.lastTs, lastRowid: result.lastRowid, lastAt: result.lastAt });
460	  }
461	  state.lastCheck = { at: cstTimeFull(Date.now()), group: gid, count: result.count, truncated: !!result.truncated };
462	  await saveState(state);
463	  if (gid === (Number(cfg.group) || DEFAULT_GROUP)) await syncWorkspaceState(cfg, result, state);
464	  return { ...result, group: gid, gid };
465	}
466	
467	/**
468	 * 导出全部受监测群的新消息：逐群推进各自游标，并把所有新消息按时间升序
469	 * 合并到一份 合订 chatlog（chatlog_增量_合订_*.txt / .jsonl）。合并逻辑
470	 * 在 wenyou_read.py pullall 子命令里完成，保证 protobuf 解析与时间标签一致。
471	 */
472	export async function doPullAll(ctx, state, cfg, maxRows, signal) {
473	  const groups = monitoredGroups(state);
474	  const specs = [];
475	  for (const { gid } of groups) {
476	    const cursor = groupCursor(state, gid);
477	    if (!cursor) continue;   // 未建立游标的群先跳过（用 /wenyou tail <gid> <n> 建立）
478	    specs.push(`${gid}:${Number(cursor.lastTs)}:${Number(cursor.lastRowid) || 0}`);
479	  }
480	  if (!specs.length) {
481	    throw new Error('没有任何群建立了游标：请先对各群执行 /wenyou tail <gid> <n> 建立游标');
482	  }
483	  const result = await runPython(
484	    ctx,
485	    ['pullall', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--groups', specs.join(','), '--out-dir', cfg.exportDir, '--max', String(Math.max(1, Math.floor(maxRows / specs.length)))],
486	    cfg.exportDir,
487	    signal,
488	  );
489	  // 推进各群游标
490	  for (const p of result.perGroup || []) {
491	    if (p.count > 0 && !p.truncated && p.lastTs != null) {
492	      await setGroupCursor(state, Number(p.gid), { lastTs: p.lastTs, lastRowid: p.lastRowid != null ? p.lastRowid : null, lastAt: p.lastAt });
493	    }
494	  }
495	  const mains = (result.perGroup || []).find((p) => Number(p.gid) === (Number(cfg.group) || DEFAULT_GROUP));
496	  if (mains) await syncWorkspaceState(cfg, { ...mains, outJsonl: path.join(cfg.exportDir, `msgs_增量_${mains.gid}.jsonl`), outTxt: path.join(cfg.exportDir, `chatlog_增量_${mains.gid}.txt`) }, state);
497	  state.lastCheck = { at: cstTimeFull(Date.now()), mode: 'pullall', count: result.combinedCount, truncated: false };
498	  await saveState(state);
499	  return result;
500	}
501	
502	export async function syncWorkspaceState(cfg, result, state) {
503	  const qmsPath = path.join(cfg.exportDir, 'qq_monitor_state.json');
504	  let qms = await readJson(qmsPath, {});
505	  if (typeof qms !== 'object' || qms === null) qms = {};
506	  qms.trigger_group = String(cfg.group);
507	  if (result.groupName) qms.trigger_group_name = result.groupName;
508	  if (state.cursor) {
509	    qms.last_reported_ts = state.cursor.lastTs;
510	    qms.last_reported_rowid = state.cursor.lastRowid;
511	    qms.last_reported_at_cst = state.cursor.lastAt;
512	  }
513	  qms.new_msgs_since_report = result.count;
514	  qms.last_export_jsonl = result.outJsonl;
515	  qms.last_export_chatlog = result.outTxt;
516	  qms.last_check_ts = Math.floor(Date.now() / 1000);
517	  qms.last_check_at_cst = cstTimeFull(Date.now());
518	  qms.state = 'monitoring';
519	  await fsp.mkdir(path.dirname(qmsPath), { recursive: true });
520	  await writeJsonAtomic(qmsPath, qms);
521	}
522	
523	/** ---------- 简报 ---------- */
524	
525	export function buildBriefPrompt(cfg, result) {
526	  const exportDir = cfg.exportDir;
527	  const topic = cfg.topic || '群岛';
528	  const briefBase = cfg.briefBase || `${topic}外交局势总结.md`;
529	  const briefPrefix = cfg.briefPrefix || `${topic}局势总结_增量_`;
530	  return [
531	    '【文游简报任务】',
532	    `请处理 QQ <QQ_GROUP_NAME_001>群 ${cfg.group}（${result.groupName || ''}）自上次以来的新增消息：`,
533	    `1. 读取新导出的聊天记录：${result.outTxt}（本次新增 ${result.count} 条消息，${result.firstAt || '?'} 至 ${result.lastAt || '?'}）。`,
534	    `2. 参考基线总结 ${path.join(exportDir, briefBase)} 与目录下最新的 \`${briefPrefix}*.md\`（若存在）。`,
535	    `3. 在 ${exportDir} 写一份新的增量总结文件，命名沿用 ${briefPrefix}MMDD.md（用本次消息最后时间），格式延续旧总结：一句话概括 / 分节事实 / 存疑与可信度提示。`,
536	    `4. 更新 ${path.join(exportDir, 'qq_monitor_state.json')}：briefing 改为本批一句话简报，new_msgs_since_report 改为 0；若能判断回合数，更新 round 字段。`,
537	    '要求：只读上面列出的文件并写新文件，不要重新解密 QQ 数据库；全部用简体中文；若本次新增消息为空则直接说明“暂无新消息”，不要创建新文件。',
538	  ].join('\n');
539	}
540	
541	/** 快速统计某群自游标以来的新增消息（只读，不解密）。 */
542	export async function quickStats(ctx, cfg, state, signal, gid) {
543	  const targetGid = gid == null ? Number(cfg.group) : Number(gid);
544	  const c = groupCursor(state, targetGid);
545	  if (!c) return null;
546	  try {
547	    return await runPython(
548	      ctx,
549	      ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(targetGid), '--since', String(Number(c.lastTs)), '--since-rowid', String(Number(c.lastRowid) || 0), '--max', String(cfg.maxMessages)],
550	      cfg.exportDir,
551	      signal,
552	    );
553	  } catch {
554	    return null;
555	  }
556	}

