1	/**
2	 * dsh-wenyou 文本格式化模块：所有展示用的文本渲染函数。
3	 * 从 index.js 拆分而来。
4	 */
5	import { DEFAULT_GROUP } from './core.js';
6	
7	export function statusText(state, cfg, quick) {
8	  const cursorValid = state.cursor && Number.isFinite(Number(state.cursor.lastTs));
9	  const lines = [
10	    '【文游监测】',
11	    `群：${cfg.group}${quick && quick.groupName ? `（${quick.groupName}）` : ''}`,
12	    `QQ：${cfg.qq}`,
13	    `数据目录：${cfg.dbDir}`,
14	    `导出目录：${cfg.exportDir}`,
15	    `游标：${cursorValid ? `${state.cursor.lastAt}（ts ${state.cursor.lastTs}）` : '未设置——首次 /wenyou pull 会从 0 全量导出（较慢），建议先确认工作区 qq_monitor_state.json'}`,
16	    `明文消息库：${cfg.plainMsgDb}`,
17	    `密钥：${cfg.keyMapPath || '（自动查找，未配置）'}`,
18	  ];
19	  if (state.lastCheck) lines.push(`上次检查：${state.lastCheck.at}，新增 ${state.lastCheck.count} 条${state.lastCheck.truncated ? '（已截断）' : ''}`);
20	  if (quick) {
21	    lines.push(`快速统计（当前明文库）：${quick.count} 条新增${quick.truncated ? '（已截断）' : ''}${quick.lastAt ? `，最新 ${quick.lastAt}` : ''}`);
22	    for (const item of quick.sample || []) lines.push(`  · ${item.text}`);
23	  }
24	  lines.push('命令：/wenyou check（检查） /wenyou pull（导出） /wenyou brief（简报） /wenyou setup（配置）');
25	  return lines.join('\n');
26	}
27	
28	export function checkText(result, wal) {
29	  const lines = [
30	    `【检查结果】群 ${result.group} 自游标以来新增 ${result.count} 条消息${result.truncated ? '（超过上限已截断，建议 /wenyou pull）' : ''}`,
31	  ];
32	  if (result.count > 0) {
33	    lines.push(`时间范围：${result.firstAt} ～ ${result.lastAt}`);
34	    for (const item of result.sample || []) lines.push(`  · ${item.text}`);
35	  } else {
36	    lines.push('没有新消息。');
37	  }
38	  if (wal) lines.push(wal);
39	  lines.push('下一步：/wenyou pull 导出，或 /wenyou brief 直接导出并生成简报。');
40	  return lines.join('\n');
41	}
42	
43	export function pullText(result, wal) {
44	  const lines = [
45	    result.count > 0
46	      ? `✅ 已导出 ${result.count} 条新消息（${result.firstAt} ～ ${result.lastAt}）${result.initialPull ? '（首次建立游标）' : ''}`
47	      : '✅ 没有新消息，未推进游标。',
48	  ];
49	  if (result.count > 0) {
50	    lines.push(`聊天记录：${result.outTxt}`);
51	    lines.push(`原始 JSONL：${result.outJsonl}`);
52	    if (result.truncated) lines.push('⚠ 本次达到导出上限，游标未推进；可用 /wenyou setup max_messages 调大后重试。');
53	    for (const item of result.sample || []) lines.push(`  · ${item.text}`);
54	  }
55	  if (wal) lines.push(wal);
56	  lines.push('下一步：/wenyou brief 生成局势简报，或直接让我总结。');
57	  return lines.join('\n');
58	}
59	
60	export function configText(state, cfg) {
61	  return [
62	    '【当前配置】',
63	    `qq = ${cfg.qq}`,
64	    `group = ${cfg.group}`,
65	    `db_dir = ${cfg.dbDir}`,
66	    `export_dir = ${cfg.exportDir}`,
67	    `key_map = ${cfg.keyMapPath || '（自动查找）'}`,
68	    `plain_msg_db = ${cfg.plainMsgDb}`,
69	    `plain_group_db = ${cfg.plainGroupDb}`,
70	    `max_messages = ${cfg.maxMessages}`,
71	    `topic = ${cfg.topic || '群岛（默认）'}`,
72	    `brief_base = ${cfg.briefBase || '（自动）'}`,
73	    `brief_prefix = ${cfg.briefPrefix || '（自动）'}`,
74	    '',
75	    '修改示例：/wenyou setup group <QQ_GROUP_001>；/wenyou setup topic 温蒂尼；/wenyou setup brief_prefix 温蒂尼局势_增量_',
76	  ].join('\n');
77	}
78	
79	export function groupsText(state, quickNames, getCursor) {
80	  const main = Number(state.config.group) || DEFAULT_GROUP;
81	  const lines = ['【受监测群】'];
82	  const extra = Array.isArray(state.config.extraGroups) ? state.config.extraGroups : [];
83	  // 用传入的 groupCursor 函数保持与 core.js 逻辑一致；未传入时回退到简单内联
84	  const cur = (gid) => {
85	    let c;
86	    if (typeof getCursor === 'function') {
87	      c = getCursor(state, gid);
88	    } else {
89	      c = main === Number(gid) ? state.cursor : (state.groups && state.groups[gid]);
90	    }
91	    return c && Number.isFinite(Number(c.lastTs)) ? c.lastAt : '（未建游标）';
92	  };
93	  lines.push(`· ${main}${quickNames && quickNames[main] ? `（${quickNames[main]}）` : ''} [主群 · 游标 ${cur(main)}]`);
94	  for (const g of extra) {
95	    const gid = Number(g && g.gid);
96	    if (!Number.isFinite(gid)) continue;
97	    const label = gid === main ? '主群' : '额外';
98	    lines.push(`· ${gid}${quickNames && quickNames[gid] ? `（${quickNames[gid]}）` : g && g.name ? `（${g.name}）` : ''} [${label} · 游标 ${cur(gid)}]`);
99	  }
100	  lines.push('用法：/wenyou tail <群号> <条数>（建立游标） /wenyou pull <群号> /wenyou pullall（合订导出） /wenyou add <群号> [名称]');
101	  return lines.join('\n');
102	}
103	
104	export function tailText(result) {
105	  const lines = [
