109	  if (result.outJsonl) lines.push(`原始 JSONL：${result.outJsonl}`);
110	  for (const item of result.sample || []) lines.push(`  · ${item.text}`);
111	  lines.push('提示：这只是逐群独立文件；要用三个群按时间合并看，请 /wenyou pullall。');
112	  return lines.join('\n');
113	}
114	
115	export function pullAllText(result) {
116	  const lines = ['【合订导出】'];
117	  if (result.combinedTxt) lines.push(`合订聊天记录：${result.combinedTxt}（共 ${result.combinedCount} 行，${result.firstAt || '?'} ～ ${result.lastAt || '?'}）`);
118	  for (const p of result.perGroup || []) {
119	    lines.push(`  · 群 ${p.gid}（${p.name || ''}）：${p.count} 条${p.truncated ? '（已截断）' : ''}`);
