                        label = row[0]
                except Exception:
                    pass
            names[str(gid)] = label
    finally:
        if conn is not None:
            conn.close()
    print("__RESULT__" + json.dumps(
        {"ok": True, "mode": "names", "names": names}, ensure_ascii=False))


