  if (g == null) return { removed: false, reason: 'invalid', gid: null };
  const main = normalizeGid(state.config.group) || DEFAULT_GROUP;
  if (g === main) return { removed: false, reason: 'main', gid: g };
  const before = Array.isArray(state.config.extraGroups) ? state.config.extraGroups : [];
  const after = before.filter((x) => normalizeGid(x && x.gid) !== g);
  state.config.extraGroups = after;
  if (state.groups) delete state.groups[g];
  if (state.groupNames) delete state.groupNames[g];
  return { removed: after.length !== before.length, reason: after.length !== before.length ? 'ok' : 'absent', gid: g };
}

/** 取某群的游标：主群用 state.cursor，其它群用 state.groups[gid]。 */
export function groupCursor(state, gid) {
  const target = normalizeGid(gid);
  if (target == null) return null;
  const main = normalizeGid(state.config.group) || DEFAULT_GROUP;
  if (target === main) {
    return state.cursor && Number.isFinite(Number(state.cursor.lastTs)) ? state.cursor : null;
  }
  const g = state.groups && state.groups[target];
  return g && Number.isFinite(Number(g.lastTs)) ? g : null;
}

/** 写某群的游标。 */
export async function setGroupCursor(state, gid, cursor) {
  const target = normalizeGid(gid);
  if (target == null) return;
  const main = normalizeGid(state.config.group) || DEFAULT_GROUP;
  if (target === main) {
    state.cursor = { ...cursor };
  } else {
    state.groups = state.groups || {};
    state.groups[target] = { ...cursor };
  }
  await saveState(state);
}

export async function loadState() {
  const raw = await readJson(STATE_FILE, null);
  return mergeState(raw);
}

/** 写盘串行化：排队时先做快照，避免排队期间 state 被继续修改写出半成品。 */
export async function saveState(state) {
  const snapshot = JSON.parse(JSON.stringify(state));
  return saveQueue(async () => {
    await fsp.mkdir(DATA_DIR, { recursive: true });
    await writeJsonAtomic(STATE_FILE, snapshot);
  });
}

export function sessionCwd(agent) {
  try {
    const cwd = agent && agent.session && agent.session.header && agent.session.header.cwd;
    return cwd || '';
  } catch {
    return '';
  }
}

/** 从工作区 qq_monitor_state.json 继承旧流程游标，保证“不漏也不重”。 */
export async function seedFromWorkspace(state, exportDir) {
  const qms = await readJson(path.join(exportDir, 'qq_monitor_state.json'), null);
  if (!qms) return false;
  // 只有用户未显式改过群号时才沿用旧工作区状态，避免 setup 被覆盖。
  const legacyGroup = normalizeGid(qms.trigger_group);
  if (legacyGroup && normalizeGid(state.config.group) === DEFAULT_GROUP) {
    state.config.group = legacyGroup;
  }
  if (typeof qms.threshold === 'number') state.config.threshold = qms.threshold;
  if (!state.cursor && typeof qms.last_reported_ts === 'number') {
    state.cursor = {
      lastTs: qms.last_reported_ts,
      lastRowid: typeof qms.last_reported_rowid === 'number' ? qms.last_reported_rowid : null,
      lastAt: qms.last_reported_at_cst || '',
    };
  }
  return true;
}

export function resolveExportDir(agent, state) {
  if (state.config.exportDir) return state.config.exportDir;
  return sessionCwd(agent) || FALLBACK_WORKSPACE;
}

export async function resolveConfig(state, agent) {
  const exportDir = resolveExportDir(agent, state);
  // 旧流程迁移只在“还没有主群游标”时做一次，避免每次调用都去读两个工作区 JSON。
  if (!(state.cursor && Number.isFinite(Number(state.cursor.lastTs)))) {
    const seen = new Set();
    for (const dir of [exportDir, FALLBACK_WORKSPACE]) {
      if (!dir || seen.has(dir)) continue;
      seen.add(dir);
      await seedFromWorkspace(state, dir);
    }
  }
  const cfg = state.config;
  const qq = cfg.qq || DEFAULT_QQ;
  const dbDir = cfg.dbDir || path.join(os.homedir(), 'Documents', 'Tencent Files', qq, 'nt_qq', 'nt_db');
  let plainMsgDb = cfg.plainMsgDb;
  if (!plainMsgDb) {
    const live = path.join(exportDir, 'nt_msg_live_plain.db');
    plainMsgDb = existsSync(live) ? live : path.join(DATA_DIR, 'plain', 'nt_msg_plain.db');
  }
  let plainGroupDb = cfg.plainGroupDb;
  if (!plainGroupDb) {
    const existing = path.join(exportDir, 'group_info_plain.db');
    plainGroupDb = existsSync(existing) ? existing : path.join(DATA_DIR, 'plain', 'group_info_plain.db');
  }
  return {
    exportDir,
    qq,
    group: normalizeGid(cfg.group) || DEFAULT_GROUP,
    extraGroups: Array.isArray(cfg.extraGroups) ? cfg.extraGroups : [],
    dbDir,
    keyMapPath: cfg.keyMapPath,
    plainMsgDb,
    plainGroupDb,
    maxMessages: Number(cfg.maxMessages) > 0 ? Number(cfg.maxMessages) : DEFAULT_MAX_MESSAGES,
    topic: String(cfg.topic || '').trim(),
    briefBase: String(cfg.briefBase || '').trim(),
    briefPrefix: String(cfg.briefPrefix || '').trim(),
  };
}

/** ---------- 子进程 ---------- */

export async function runProcess(ctx, argv, cwd, signal) {
  const proc = ctx.subprocess.spawn({
    argv,
    cwd,
    graceMs: 5000,
    signal,
    stdio: {
      stdin: 'ignore',
      // stdout 里承载 __RESULT__ JSON（含样例文本），头部上限给足，避免结果被截掉。
      stdout: { maxBytes: 1 << 20, spill: { maxBytes: 1 << 23 } },
      stderr: { maxBytes: 1 << 16, spill: { maxBytes: 1 << 22 } },
    },
  });
  const outcome = await proc.done;
  const out = proc.collected.stdout?.readFrom(0).text ?? '';
  const err = proc.collected.stderr?.readFrom(0).text ?? '';
  if (outcome.exitCode !== 0) {
    throw new Error(\`命令失败 exit=\${outcome.exitCode}: \${err || out}\`);
  }
  return { out, err };
}

let cachedPython = null;

export async function findPython(ctx, signal) {
  if (cachedPython) return cachedPython;
  const candidates = [
    process.env.WENYOU_PYTHON,
    path.join(os.homedir(), '.cache', 'codex-runtimes', 'codex-primary-runtime', 'dependencies', 'python', 'python.exe'),
    'python',
    'py',
  ].filter(Boolean);
  for (const candidate of candidates) {
    try {
      cachedPython = await ctx.subprocess.resolveExecutable(candidate, undefined, signal);
      return cachedPython;
    } catch {
      // 尝试下一个
    }
  }
  throw new Error('未找到 Python：请安装 Python 3 或用环境变量 WENYOU_PYTHON 指向 python.exe');
}

export async function runPython(ctx, args, cwd, signal) {
  const python = await findPython(ctx, signal);
  const { out } = await runProcess(ctx, [python, WENYOU_READ_PY, ...args], cwd, signal);
  // 从后往前找 __RESULT__ 行：即使脚本尾部混入了别的 stdout 也能取到结果。
  const lines = out.split(/\\r?\\n/);
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const line = lines[i].trim();
    if (line.startsWith('__RESULT__')) {
      return JSON.parse(line.slice('__RESULT__'.length));
    }
  }
  throw new Error(\`wenyou_read.py 未返回结果：\${out.slice(-400)}\`);
}

/** 导出某群最近 n 条消息（time 升序），用于初次建立游标 / 回看尾巴。 */
export async function runTail(ctx, cfg, group, n, outJsonl, outTxt, signal) {
  return runPython(
    ctx,
    ['tail', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(group), '--n', String(n), '--out-jsonl', outJsonl, '--out-txt', outTxt],
    cfg.exportDir,
    signal,
  );
}

/**
 * 批量解析群名（只读 group_info 明文库，一次子进程搞定）。
 * 命中 state.groupNames 缓存的群不再查库；查到的新名字写回缓存。
 */
export async function resolveGroupNames(ctx, cfg, state, gids, signal) {
  const wanted = [...new Set((gids || []).map(normalizeGid).filter((x) => x != null))];
  state.groupNames = state.groupNames && typeof state.groupNames === 'object' ? state.groupNames : {};
  const names = {};
  const missing = [];
  for (const gid of wanted) {
    const cached = state.groupNames[gid];
    if (cached) names[gid] = String(cached);
    else missing.push(gid);
  }
  if (missing.length && cfg.plainGroupDb && existsSync(cfg.plainGroupDb)) {
    try {
      const res = await runPython(
        ctx,
        ['names', '--group-db', cfg.plainGroupDb, '--groups', missing.join(',')],
        cfg.exportDir,
        signal,
      );
      let dirty = false;
      for (const [key, value] of Object.entries((res && res.names) || {})) {
        const gid = normalizeGid(key);
        // 读不到名字时 python 会回落成群号字符串，那种“名字”不值得缓存。
        if (gid == null || !value || String(value) === String(gid)) continue;
        names[gid] = String(value);
        state.groupNames[gid] = String(value);
        dirty = true;
      }
      if (dirty) await saveState(state);
    } catch {
      // 名称仅作展示，读不到不阻塞主流程
    }
  }
  // 兜底：用户 /wenyou add 时手写的名字
  for (const g of state.config.extraGroups || []) {
    const gid = normalizeGid(g && g.gid);
    if (gid != null && !names[gid] && g.name) names[gid] = String(g.name);
  }
  return names;
}

/** ---------- 密钥 ---------- */

export async function ensureKeyMap(ctx, cfg, signal) {
  // 扫描候选：用户配置 > 环境变量 > 已知默认位置 > 插件数据目录
  const candidates = [
    cfg.keyMapPath,
    process.env.WENYOU_KEY_MAP,
    path.join(os.homedir(), '.codex', 'skills', 'qq-chat-reader', 'keys', 'key_map.json'),
    path.join(os.homedir(), 'Documents', 'Codex', '2026-08-04', 'qq-3', 'work', 'tools', 'qq_dump_db', 'output', String(cfg.qq), 'key_map.json'),
    path.join(DATA_DIR, 'key_map.json'),
  ].filter(Boolean);
  for (const candidate of candidates) {
    try {
      const st = await fsp.stat(candidate);
      if (st.isFile() && st.size > 0) return candidate;
    } catch {
      // 不存在，继续找
    }
  }

  if (!existsSync(QQ_DUMP_EXE)) {
    throw new Error('未找到 key_map.json，且插件缺少 qq_dump_db.exe，无法提取密钥');
  }
  const target = path.join(DATA_DIR, 'key_map.json');
  await fsp.mkdir(DATA_DIR, { recursive: true });
  const proc = ctx.subprocess.spawn({
    argv: [QQ_DUMP_EXE, '--qq', String(cfg.qq), '--output', target],
    cwd: DATA_DIR,
    graceMs: 5000,
    signal,
    stdio: {
      stdin: 'ignore',
      stdout: { maxBytes: 4096, spill: { maxBytes: 1 << 18 } },
      stderr: { maxBytes: 4096, spill: { maxBytes: 1 << 18 } },
    },
  });
  let timer = null;
  try {
    const outcome = await Promise.race([
      proc.done,
      new Promise((_, reject) => {
        timer = setTimeout(
          () => reject(new Error('密钥提取超时：请确认 QQ 已登录且为 NTQQ 新版，然后重试')),
          KEY_DUMP_TIMEOUT_MS,
        );
      }),
    ]);
    if (outcome.exitCode !== 0) {
      const err = proc.collected.stderr?.readFrom(0).text ?? '';
      throw new Error(\`密钥提取失败 exit=\${outcome.exitCode}: \${err}\`);
    }
    const st = await fsp.stat(target);
    if (st.isFile() && st.size > 0) return target;
    throw new Error('密钥提取失败：未生成 key_map.json');
  } finally {
    if (timer) clearTimeout(timer);   // 成功路径也要清掉定时器，别把 node 事件循环吊住
    try {
      await proc.terminate();
    } catch {
      // 进程可能已自行退出
    }
  }
}

/** ---------- 解密 ---------- */

/** 解密串行化入口：并发调用会排队，后来者通常直接命中“已是新鲜明文库”而跳过。 */
export async function ensureDecrypted(ctx, state, cfg, force, signal) {
  return decryptQueue(() => ensureDecryptedInner(ctx, state, cfg, force, signal));
}

async function ensureDecryptedInner(ctx, state, cfg, force, signal) {
  const keyMapPath = await ensureKeyMap(ctx, cfg, signal);
  const targets = [
    { key: 'msg', label: '消息库', src: path.join(cfg.dbDir, 'nt_msg.db'), out: cfg.plainMsgDb },
    { key: 'group', label: '群资料库', src: path.join(cfg.dbDir, 'group_info.db'), out: cfg.plainGroupDb },
  ];
  const report = [];
  for (const item of targets) {
    let srcStat;
    try {
      srcStat = await fsp.stat(item.src);
    } catch {
      throw new Error(\`找不到 QQ \${item.label}：\${item.src}（请确认 QQ 数据目录，或 /wenyou setup db_dir <目录>）\`);
    }
    let outStat = null;
    try {
      outStat = await fsp.stat(item.out);
    } catch {
      outStat = null;
    }
    // 明文库是在源库之后（或同一时刻之后）生成的，就认为可用；比持久化的
    // mtime+size 更稳，因为源库可能在解密过程中被 QQ 又写入。
    const fresh = !force
      && outStat !== null
      && outStat.size > 0
      && outStat.mtimeMs >= srcStat.mtimeMs;
    if (fresh) {
      report.push({ ...item, skipped: true });
      continue;
    }
    await fsp.mkdir(path.dirname(item.out), { recursive: true });
    await runProcess(
      ctx,
      [process.execPath, QQ_DECRYPT_CJS, item.src, item.out, keyMapPath],
      ASSETS,
      signal,
    );
    state.lastDecrypt[item.key] = {
      src: item.src,
      mtimeMs: srcStat.mtimeMs,
      size: srcStat.size,
      at: cstTimeFull(Date.now()),
    };
    // 群资料库换新之后，缓存的群名可能已过期，清掉让下次重新解析。
    if (item.key === 'group') state.groupNames = {};
    await saveState(state);
    report.push({ ...item, skipped: false });
  }
  return { keyMapPath, report };
}

export async function walWarning(cfg) {
  const wal = path.join(cfg.dbDir, 'nt_msg.db-wal');
  try {
    const st = await fsp.stat(wal);
    if (st.size > 256 * 1024) {
      return \`提示：QQ 的 WAL 暂存文件还有 \${(st.size / 1024 / 1024).toFixed(1)} MB 未归并，最新消息可能不在主库中；若新增数偏少，等一会再试或正常退出 QQ 后重试。\`;
    }
  } catch {
    // 没有 WAL，无需提示
  }
  return '';
}

/** ---------- 核心操作 ---------- */

export function cursorSince(state) {
  if (state.cursor && Number.isFinite(Number(state.cursor.lastTs))) {
    return { since: Number(state.cursor.lastTs), fresh: true };
  }
  return { since: 0, fresh: false };
}

function requireCursor(state, gid) {
  const cursor = groupCursor(state, gid);
  if (!cursor) {
    throw new Error(\`群 \${gid} 游标尚未设置：请先执行 /wenyou tail \${gid} 500 建立游标\`);
  }
  return cursor;
}

/** 检查某群（默认主群）自其游标以来的新增消息。 */
export async function doCheck(ctx, state, cfg, maxRows, signal, group) {
  const gid = normalizeGid(group == null ? cfg.group : group);
  if (gid == null) throw new Error('群号非法');
  const cursor = requireCursor(state, gid);
  const since = Number(cursor.lastTs);
  const sinceRowid = Number(cursor.lastRowid) || 0;
  const result = await runPython(
    ctx,
    ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(gid), '--since', String(since), '--since-rowid', String(sinceRowid), '--max', String(maxRows)],
    cfg.exportDir,
    signal,
  );
  if (result.groupName && String(result.groupName) !== String(gid)) {
    state.groupNames = state.groupNames || {};
    state.groupNames[gid] = String(result.groupName);
  }
  state.lastCheck = { at: cstTimeFull(Date.now()), group: gid, count: result.count, truncated: !!result.truncated };
  await saveState(state);
  return { ...result, group: gid, gid };
}

/** 导出某群（默认主群）自其游标以来的新消息并推进该群游标。 */
export async function doPull(ctx, state, cfg, maxRows, signal, group) {
  const gid = normalizeGid(group == null ? cfg.group : group);
  if (gid == null) throw new Error('群号非法');
  const cursor = requireCursor(state, gid);
  const since = Number(cursor.lastTs);
  const sinceRowid = Number(cursor.lastRowid) || 0;
  const outJsonl = path.join(cfg.exportDir, \`msgs_增量_\${gid}.jsonl\`);
  const outTxt = path.join(cfg.exportDir, \`chatlog_增量_\${gid}.txt\`);
  const result = await runPython(
    ctx,
    [
      'pull',
      '--db', cfg.plainMsgDb,
      '--group-db', cfg.plainGroupDb,
      '--group', String(gid),
      '--since', String(since),
      '--since-rowid', String(sinceRowid),
      '--out-jsonl', outJsonl,
      '--out-txt', outTxt,
      '--max', String(maxRows),
    ],
    cfg.exportDir,
    signal,
  );
  if (result.groupName && String(result.groupName) !== String(gid)) {
    state.groupNames = state.groupNames || {};
    state.groupNames[gid] = String(result.groupName);
  }
  if (result.count > 0 && !result.truncated) {
    await setGroupCursor(state, gid, { lastTs: result.lastTs, lastRowid: result.lastRowid, lastAt: result.lastAt });
  }
  state.lastCheck = { at: cstTimeFull(Date.now()), group: gid, count: result.count, truncated: !!result.truncated };
  await saveState(state);
  if (gid === (normalizeGid(cfg.group) || DEFAULT_GROUP)) await syncWorkspaceState(cfg, result, state);
  return { ...result, group: gid, gid };
}

/**
 * 导出全部受监测群的新消息：逐群推进各自游标，并把所有新消息按时间升序
 * 合并到一份 合订 chatlog（chatlog_增量_合订_*.txt / .jsonl）。合并逻辑
 * 在 wenyou_read.py pullall 子命令里完成，保证 protobuf 解析与时间标签一致。
 */
export async function doPullAll(ctx, state, cfg, maxRows, signal) {
  const groups = monitoredGroups(state);
  const specs = [];
  const pending = [];
  for (const { gid } of groups) {
    const cursor = groupCursor(state, gid);
    if (!cursor) {
      pending.push(gid);   // 未建立游标的群先跳过（用 /wenyou tail <gid> <n> 建立）
      continue;
    }
    specs.push(\`\${gid}:\${Number(cursor.lastTs)}:\${Number(cursor.lastRowid) || 0}\`);
  }
  if (!specs.length) {
    throw new Error('没有任何群建立了游标：请先对各群执行 /wenyou tail <gid> <n> 建立游标');
  }
  const result = await runPython(
    ctx,
    ['pullall', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--groups', specs.join(','), '--out-dir', cfg.exportDir, '--max', String(Math.max(1, Math.floor(maxRows / specs.length)))],
    cfg.exportDir,
    signal,
  );
  // 推进各群游标
  for (const p of result.perGroup || []) {
    const gid = normalizeGid(p.gid);
    if (gid == null) continue;
    if (p.name && String(p.name) !== String(gid)) {
      state.groupNames = state.groupNames || {};
      state.groupNames[gid] = String(p.name);
    }
    if (p.count > 0 && !p.truncated && p.lastTs != null) {
      await setGroupCursor(state, gid, { lastTs: p.lastTs, lastRowid: p.lastRowid != null ? p.lastRowid : null, lastAt: p.lastAt });
    }
  }
  const mainGid = normalizeGid(cfg.group) || DEFAULT_GROUP;
  const mains = (result.perGroup || []).find((p) => normalizeGid(p.gid) === mainGid);
  if (mains) {
    await syncWorkspaceState(cfg, {
      ...mains,
      groupName: mains.name,
      outJsonl: path.join(cfg.exportDir, \`msgs_增量_\${mainGid}.jsonl\`),
      outTxt: path.join(cfg.exportDir, \`chatlog_增量_\${mainGid}.txt\`),
    }, state);
  }
  state.lastCheck = { at: cstTimeFull(Date.now()), mode: 'pullall', count: result.combinedCount, truncated: false };
  await saveState(state);
  return { ...result, pendingGroups: pending };
}

export async function syncWorkspaceState(cfg, result, state) {
  const qmsPath = path.join(cfg.exportDir, 'qq_monitor_state.json');
  let qms = await readJson(qmsPath, {});
  if (typeof qms !== 'object' || qms === null) qms = {};
  qms.trigger_group = normalizeGid(cfg.group) || DEFAULT_GROUP;
  if (result.groupName) qms.trigger_group_name = result.groupName;
  if (state.cursor) {
    qms.last_reported_ts = state.cursor.lastTs;
    qms.last_reported_rowid = state.cursor.lastRowid;
    qms.last_reported_at_cst = state.cursor.lastAt;
  }
  qms.new_msgs_since_report = result.count;
  qms.last_export_jsonl = result.outJsonl;
  qms.last_export_chatlog = result.outTxt;
  qms.last_check_ts = Math.floor(Date.now() / 1000);
  qms.last_check_at_cst = cstTimeFull(Date.now());
  qms.state = 'monitoring';
  await fsp.mkdir(path.dirname(qmsPath), { recursive: true });
  await writeJsonAtomic(qmsPath, qms);
}

/** ---------- 简报 ---------- */

export function buildBriefPrompt(cfg, result) {
  const exportDir = cfg.exportDir;
  const topic = cfg.topic || '群岛';
  const briefBase = cfg.briefBase || \`\${topic}外交局势总结.md\`;
  const briefPrefix = cfg.briefPrefix || \`\${topic}局势总结_增量_\`;
  const gid = result.group != null ? result.group : cfg.group;
  return [
    '【文游简报任务】',
    \`请处理 QQ <QQ_GROUP_NAME_001>群 \${gid}（\${result.groupName || ''}）自上次以来的新增消息：\`,
    \`1. 读取新导出的聊天记录：\${result.outTxt}（本次新增 \${result.count} 条消息，\${result.firstAt || '?'} 至 \${result.lastAt || '?'}）。\`,
