export async function runProcess(ctx, argv, cwd, signal) {
  const proc = ctx.subprocess.spawn({
    argv,
    cwd,
    graceMs: 5000,
    signal,
    stdio: {
      stdin: 'ignore',
      // stdout 里承载 __RESULT__ JSON（含样例文本），头部上限给足，避免结果被截掉。
      stdout: { maxBytes: 1 << 20, spill: { maxBytes: 1 << 23 } },
      stderr: { maxBytes: 1 << 16, spill: { maxBytes: 1 << 22 } },
    },
  });
  const outcome = await proc.done;
  const out = proc.collected.stdout?.readFrom(0).text ?? '';
  const err = proc.collected.stderr?.readFrom(0).text ?? '';
  if (outcome.exitCode !== 0) {
    throw new Error(\`命令失败 exit=\${outcome.exitCode}: \${err || out}\`);
  }
  return { out, err };
}

