    try {
      cachedPython = await ctx.subprocess.resolveExecutable(candidate, undefined, signal);
      return cachedPython;
    } catch {
      // 尝试下一个
    }
  }
  throw new Error('未找到 Python：请安装 Python 3 或用环境变量 WENYOU_PYTHON 指向 python.exe');
}

export async function runPython(ctx, args, cwd, signal) {
  const python = await findPython(ctx, signal);
  const { out } = await runProcess(ctx, [python, WENYOU_READ_PY, ...args], cwd, signal);
  // 从后往前找 __RESULT__ 行：即使脚本尾部混入了别的 stdout 也能取到结果。
  const lines = out.split(/\\r?\\n/);
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const line = lines[i].trim();
    if (line.startsWith('__RESULT__')) {
      return JSON.parse(line.slice('__RESULT__'.length));
    }
  }
  throw new Error(\`wenyou_read.py 未返回结果：\${out.slice(-400)}\`);
}

