  const proc = ctx.subprocess.spawn({
    argv: [QQ_DUMP_EXE, '--qq', String(cfg.qq), '--output', target],
    cwd: DATA_DIR,
    graceMs: 5000,
    signal,
    stdio: {
      stdin: 'ignore',
      stdout: { maxBytes: 4096, spill: { maxBytes: 1 << 18 } },
      stderr: { maxBytes: 4096, spill: { maxBytes: 1 << 18 } },
    },
  });
