 * dsh-wenyou 核心逻辑模块：状态管理、子进程、密钥/解密、导入导出。
 *
 * 约定：
 *   - 群号一律在入口归一化为 number（历史 state.json 里存过字符串，混用会导致比较失败）；
 *   - 状态写盘与数据库解密都经过串行队列，禁止并发（避免 tmp 互踩 / 2.3GB 库被重复解密）；
 *   - 展示用的群名走 state.groupNames 缓存 + 只读 names 子命令，不再为取名去开消息库。
 */
import { promises as fsp } from 'node:fs';
import { existsSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = path.resolve(HERE, '..');
const ASSETS = path.join(PLUGIN_ROOT, 'assets');
export const QQ_DECRYPT_CJS = path.join(ASSETS, 'qq_decrypt.cjs');
export const QQ_DUMP_EXE = path.join(ASSETS, 'qq_dump_db.exe');
export const WENYOU_READ_PY = path.join(ASSETS, 'wenyou_read.py');

export const DSH_HOME = process.env.DSH_HOME || path.join(os.homedir(), '.dsh');
export const DATA_DIR = path.join(DSH_HOME, 'storages', 'dsh-wenyou');
export const STATE_FILE = path.join(DATA_DIR, 'state.json');

export const DEFAULT_QQ = '<QQ_ACCOUNT_001>';
export const DEFAULT_GROUP = <QQ_GROUP_001>;
export const DEFAULT_MAX_MESSAGES = 20000;
export const MAX_MESSAGES_LIMIT = 200000;
export const KEY_DUMP_TIMEOUT_MS = Number(process.env.WENYOU_KEY_TIMEOUT_MS) > 0
  ? Number(process.env.WENYOU_KEY_TIMEOUT_MS)
  : 45000;
// 可从环境变量覆盖的 fallback workspace（跨机器不写死）
export const FALLBACK_WORKSPACE = process.env.WENYOU_FALLBACK_WORKSPACE
  || path.join(os.homedir(), 'Downloads', 'deepseek-harness', '温蒂尼局势');

export function pad(n) {
  return String(n).padStart(2, '0');
}

/** 把毫秒时间戳格式化成 CST 可读串（不用 Date 的本地时区假设）。 */
export function cstTime(ms) {
  const d = new Date(ms + 8 * 3600 * 1000);
  return \`\${d.getUTCFullYear()}-\${pad(d.getUTCMonth() + 1)}-\${pad(d.getUTCDate())} \${pad(d.getUTCHours())}:\${pad(d.getUTCMinutes())}\`;
}

export function cstTimeFull(ms) {
  const d = new Date(ms + 8 * 3600 * 1000);
  return \`\${d.getUTCFullYear()}-\${pad(d.getUTCMonth() + 1)}-\${pad(d.getUTCDate())} \${pad(d.getUTCHours())}:\${pad(d.getUTCMinutes())}:\${pad(d.getUTCSeconds())}\`;
}

export function errorText(err) {
  return String(err && err.message ? err.message : err);
}

/** 群号归一化：接受 number/字符串，非法返回 null。 */
export function normalizeGid(value) {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : null;
}

/** max_messages 校验（命令与工具共用，行为一致）。 */
export function parseMaxMessages(value, cfg) {
  if (value === undefined || value === null || value === '') {
    return { value: cfg.maxMessages };
  }
  const n = Number(value);
  if (!Number.isFinite(n) || n < 1 || n > MAX_MESSAGES_LIMIT) {
    return { error: \`max_messages 需在 1~\${MAX_MESSAGES_LIMIT} 之间\` };
  }
  return { value: Math.floor(n) };
}

/** 串行队列：同一队列内的任务按提交顺序执行，前一个失败不阻塞后一个。 */
function makeQueue() {
  let tail = Promise.resolve();
  return function enqueue(fn) {
    const result = tail.then(fn);
    tail = result.then(() => undefined, () => undefined);
    return result;
  };
}
const saveQueue = makeQueue();
const decryptQueue = makeQueue();

export async function writeJsonAtomic(file, value) {
  const tmp = \`\${file}.tmp\`;
  await fsp.writeFile(tmp, JSON.stringify(value, null, 2), 'utf8');
  try {
    await fsp.rename(tmp, file);
  } catch {
    await fsp.rm(file, { force: true });
    await fsp.rename(tmp, file);
  }
}

export async function readJson(file, fallback) {
  try {
    return JSON.parse(await fsp.readFile(file, 'utf8'));
  } catch {
    return fallback;
  }
}

export function defaults() {
  return {
    version: 1,
    config: {
      qq: DEFAULT_QQ,
      group: DEFAULT_GROUP,
      dbDir: '',
      exportDir: '',
      keyMapPath: '',
      plainMsgDb: '',
      plainGroupDb: '',
      maxMessages: DEFAULT_MAX_MESSAGES,
      extraGroups: [],   // 额外监测群：[{ gid: <number>, name: '' }, ...]
      topic: '',         // 文游主题名（用于简报与增量文件命名；空=用默认「群岛」）
      briefBase: '',     // 基线总结文件名（空=自动生成 <topic>外交局势总结.md）
      briefPrefix: '',   // 增量总结文件前缀（空=自动生成 <topic>局势总结_增量_）
    },
    cursor: null,
    groups: {},          // 每个群的独立游标：{ <gid>: { lastTs, lastRowid, lastAt } }
    groupNames: {},      // 群名缓存：{ <gid>: '群名' }，只为展示，可随时重建
    lastDecrypt: {},
    lastCheck: null,
  };
}

/** 额外监测群去重 + 归一化（历史状态里出现过重复条目与字符串群号）。 */
function normalizeExtraGroups(list, mainGid) {
  const out = [];
  const seen = new Set([mainGid]);
  for (const item of Array.isArray(list) ? list : []) {
    const gid = normalizeGid(item && item.gid);
    if (gid == null || seen.has(gid)) continue;
    seen.add(gid);
    out.push({ gid, name: String((item && item.name) || '') });
  }
  return out;
}

export function mergeState(raw) {
  const base = defaults();
  if (!raw || typeof raw !== 'object') return base;
  base.config = { ...base.config, ...(raw.config || {}) };
  base.config.group = normalizeGid(base.config.group) || DEFAULT_GROUP;
  base.config.maxMessages = Number(base.config.maxMessages) > 0
    ? Math.floor(Number(base.config.maxMessages))
    : DEFAULT_MAX_MESSAGES;
  base.config.extraGroups = normalizeExtraGroups(base.config.extraGroups, base.config.group);
  base.cursor = raw.cursor && typeof raw.cursor === 'object' ? { ...raw.cursor } : null;
  base.groups = raw.groups && typeof raw.groups === 'object' ? raw.groups : {};
  base.groupNames = raw.groupNames && typeof raw.groupNames === 'object' ? raw.groupNames : {};
  base.lastDecrypt = raw.lastDecrypt && typeof raw.lastDecrypt === 'object' ? raw.lastDecrypt : {};
  base.lastCheck = raw.lastCheck || null;
  return base;
}
`;
const r = await tools.write({ file_path: dir + "core.part1.js", content: part1 });
return `${r.operation} ${r.path} ${part1.length}`;
