}

async function ensureDecryptedInner(ctx, state, cfg, force, signal) {
  const keyMapPath = await ensureKeyMap(ctx, cfg, signal);
  const targets = [
    { key: 'msg', label: '消息库', src: path.join(cfg.dbDir, 'nt_msg.db'), out: cfg.plainMsgDb },
    { key: 'group', label: '群资料库', src: path.join(cfg.dbDir, 'group_info.db'), out: cfg.plainGroupDb },
  ];
  const report = [];
  for (const item of targets) {
    let srcStat;
    try {
      srcStat = await fsp.stat(item.src);
    } catch {
      throw new Error(\`找不到 QQ \${item.label}：\${item.src}（请确认 QQ 数据目录，或 /wenyou setup db_dir <目录>）\`);
    }
    let outStat = null;
    try {
      outStat = await fsp.stat(item.out);
    } catch {
      outStat = null;
