  const cursor = requireCursor(state, gid);
  const since = Number(cursor.lastTs);
  const sinceRowid = Number(cursor.lastRowid) || 0;
  const outJsonl = path.join(cfg.exportDir, \`msgs_增量_\${gid}.jsonl\`);
  const outTxt = path.join(cfg.exportDir, \`chatlog_增量_\${gid}.txt\`);
  const result = await runPython(
    ctx,
    [
      'pull',
      '--db', cfg.plainMsgDb,
      '--group-db', cfg.plainGroupDb,
      '--group', String(gid),
      '--since', String(since),
      '--since-rowid', String(sinceRowid),
      '--out-jsonl', outJsonl,
      '--out-txt', outTxt,
      '--max', String(maxRows),
