    await setGroupCursor(state, gid, { lastTs: result.lastTs, lastRowid: result.lastRowid, lastAt: result.lastAt });
  }
  state.lastCheck = { at: cstTimeFull(Date.now()), group: gid, count: result.count, truncated: !!result.truncated };
