  }
  if (!specs.length) {
    throw new Error('没有任何群建立了游标：请先对各群执行 /wenyou tail <gid> <n> 建立游标');
  }
  const result = await runPython(
    ctx,
    ['pullall', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--groups', specs.join(','), '--out-dir', cfg.exportDir, '--max', String(Math.max(1, Math.floor(maxRows / specs.length)))],
    cfg.exportDir,
    signal,
  );
  for (const p of result.perGroup || []) {
    const gid = normalizeGid(p.gid);
    if (gid == null) continue;
    rememberName(state, gid, p.name);
    if (p.count > 0 && !p.truncated && p.lastTs != null) {
      await setGroupCursor(state, gid, { lastTs: p.lastTs, lastRowid: p.lastRowid != null ? p.lastRowid : null, lastAt: p.lastAt });
    }
  }
  const mainGid = normalizeGid(cfg.group) || DEFAULT_GROUP;
  const mains = (result.perGroup || []).find((p) => normalizeGid(p.gid) === mainGid);
  if (mains) {
    await syncWorkspaceState(cfg, {
      ...mains,
      groupName: mains.name,
      outJsonl: path.join(cfg.exportDir, \`msgs_增量_\${mainGid}.jsonl\`),
      outTxt: path.join(cfg.exportDir, \`chatlog_增量_\${mainGid}.txt\`),
    }, state);
  }
  state.lastCheck = { at: cstTimeFull(Date.now()), mode: 'pullall', count: result.combinedCount, truncated: false };
  await saveState(state);
  return { ...result, pendingGroups: pending };
}

export async function syncWorkspaceState(cfg, result, state) {
  const qmsPath = path.join(cfg.exportDir, 'qq_monitor_state.json');
  let qms = await readJson(qmsPath, {});
  if (typeof qms !== 'object' || qms === null) qms = {};
  qms.trigger_group = normalizeGid(cfg.group) || DEFAULT_GROUP;
  if (result.groupName) qms.trigger_group_name = result.groupName;
  if (state.cursor) {
    qms.last_reported_ts = state.cursor.lastTs;
    qms.last_reported_rowid = state.cursor.lastRowid;
    qms.last_reported_at_cst = state.cursor.lastAt;
  }
  qms.new_msgs_since_report = result.count;
  qms.last_export_jsonl = result.outJsonl;
  qms.last_export_chatlog = result.outTxt;
  qms.last_check_ts = Math.floor(Date.now() / 1000);
