export async function doPullAll(ctx, state, cfg, maxRows, signal) {
  const groups = monitoredGroups(state);
  const specs = [];
  const pending = [];
  for (const { gid } of groups) {
    const cursor = groupCursor(state, gid);
    if (!cursor) {
      pending.push(gid);   // 未建游标的群跳过（用 /wenyou tail <gid> <n> 建立）
      continue;
    }
    specs.push(`${gid}:${Number(cursor.lastTs)}:${Number(cursor.lastRowid) || 0}`);
  }
  if (!specs.length) {
    throw new Error('没有任何群建立了游标：请先对各群执行 /wenyou tail <gid> <n> 建立游标');
  }
  const result = await runPython(
    ctx,
    ['pullall', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--groups', specs.join(','), '--out-dir', cfg.exportDir, '--max', String(Math.max(1, Math.floor(maxRows / specs.length)))],
    cfg.exportDir,
    signal,
  );
  for (const p of result.perGroup || []) {
    const gid = normalizeGid(p.gid);
    if (gid == null) continue;
    rememberName(state, gid, p.name);
    if (p.count > 0 && !p.truncated && p.lastTs != null) {
      await setGroupCursor(state, gid, { lastTs: p.lastTs, lastRowid: p.lastRowid != null ? p.lastRowid : null, lastAt: p.lastAt });
    }
  }
  const mainGid = normalizeGid(cfg.group) || DEFAULT_GROUP;
  const mains = (result.perGroup || []).find((p) => normalizeGid(p.gid) === mainGid);
  if (mains) {
    await syncWorkspaceState(cfg, {
      ...mains,
      groupName: mains.name,
      outJsonl: path.join(cfg.exportDir, `msgs_增量_${mainGid}.jsonl`),
      outTxt: path.join(cfg.exportDir, `chatlog_增量_${mainGid}.txt`),
    }, state);
  }
  state.lastCheck = { at: cstTimeFull(Date.now()), mode: 'pullall', count: result.combinedCount, truncated: false };
  await saveState(state);
  return { ...result, pendingGroups: pending };
}

export async function syncWorkspaceState(cfg, result, state) {
  const qmsPath = path.join(cfg.exportDir, 'qq_monitor_state.json');
  let qms = await readJson(qmsPath, {});
  if (typeof qms !== 'object' || qms === null) qms = {};
  qms.trigger_group = normalizeGid(cfg.group) || DEFAULT_GROUP;
  if (result.groupName) qms.trigger_group_name = result.groupName;
  if (state.cursor) {
    qms.last_reported_ts = state.cursor.lastTs;
    qms.last_reported_rowid = state.cursor.lastRowid;
    qms.last_reported_at_cst = state.cursor.lastAt;
  }
  qms.new_msgs_since_report = result.count;
  qms.last_export_jsonl = result.outJsonl;
  qms.last_export_chatlog = result.outTxt;
  qms.last_check_ts = Math.floor(Date.now() / 1000);
  qms.last_check_at_cst = cstTimeFull(Date.now());
  qms.state = 'monitoring';
  await fsp.mkdir(path.dirname(qmsPath), { recursive: true });
  await writeJsonAtomic(qmsPath, qms);
}

/** ---------- 简报 ---------- */

export function buildBriefPrompt(cfg, result) {
  const exportDir = cfg.exportDir;
  const topic = cfg.topic || '群岛';
  const briefBase = cfg.briefBase || `${topic}外交局势总结.md`;
  const briefPrefix = cfg.briefPrefix || `${topic}局势总结_增量_`;
  const gid = result.group != null ? result.group : cfg.group;
  return [
    '【文游简报任务】',
    `请处理 QQ <QQ_GROUP_NAME_001>群 ${gid}（${result.groupName || ''}）自上次以来的新增消息：`,
    `1. 读取新导出的聊天记录：${result.outTxt}（本次新增 ${result.count} 条消息，${result.firstAt || '?'} 至 ${result.lastAt || '?'}）。`,
    `2. 参考基线总结 ${path.join(exportDir, briefBase)} 与目录下最新的 \`${briefPrefix}*.md\`（若存在）。`,
    `3. 在 ${exportDir} 写一份新的增量总结文件，命名沿用 ${briefPrefix}MMDD.md（用本次消息最后时间），格式延续旧总结：一句话概括 / 分节事实 / 存疑与可信度提示。`,
    `4. 更新 ${path.join(exportDir, 'qq_monitor_state.json')}：briefing 改为本批一句话简报，new_msgs_since_report 改为 0；若能判断回合数，更新 round 字段。`,
    '要求：只读上面列出的文件并写新文件，不要重新解密 QQ 数据库；全部用简体中文；若本次新增消息为空则直接说明“暂无新消息”，不要创建新文件。',
  ].join('\n');
}

/** 快速统计某群自游标以来的新增消息（只读，不解密）。 */
export async function quickStats(ctx, cfg, state, signal, gid) {
  const targetGid = normalizeGid(gid == null ? cfg.group : gid);
  if (targetGid == null) return null;
  const c = groupCursor(state, targetGid);
  if (!c) return null;
  try {
    return await runPython(
      ctx,
      ['check', '--db', cfg.plainMsgDb, '--group-db', cfg.plainGroupDb, '--group', String(targetGid), '--since', String(Number(c.lastTs)), '--since-rowid', String(Number(c.lastRowid) || 0), '--max', String(cfg.maxMessages)],
      cfg.exportDir,
      signal,
    );
  } catch {
    return null;
  }
}

/** ---------- 解密 ---------- */

/** 解密串行化入口：并发调用排队执行，后来者通常直接命中“明文库已新鲜”而跳过。 */
export async function ensureDecrypted(ctx, state, cfg, force, signal) {
  return decryptQueue(() => ensureDecryptedInner(ctx, state, cfg, force, signal));
}

async function ensureDecryptedInner(ctx, state, cfg, force, signal) {
  const keyMapPath = await ensureKeyMap(ctx, cfg, signal);
  const targets = [
    { key: 'msg', label: '消息库', src: path.join(cfg.dbDir, 'nt_msg.db'), out: cfg.plainMsgDb },
    { key: 'group', label: '群资料库', src: path.join(cfg.dbDir, 'group_info.db'), out: cfg.plainGroupDb },
  ];
  const report = [];
  for (const item of targets) {
    let srcStat;
    try {
      srcStat = await fsp.stat(item.src);
    } catch {
      throw new Error(`找不到 QQ ${item.label}：${item.src}（请确认 QQ 数据目录，或 /wenyou setup db_dir <目录>）`);
    }
    let outStat = null;
    try {
      outStat = await fsp.stat(item.out);
    } catch {
      outStat = null;
    }
    // 明文库是在源库之后（或同一时刻之后）生成的，就认为可用；比持久化的
    // mtime+size 更稳，因为源库可能在解密过程中被 QQ 又写入。
    const fresh = !force
      && outStat !== null
      && outStat.size > 0
      && outStat.mtimeMs >= srcStat.mtimeMs;
    if (fresh) {
      report.push({ ...item, skipped: true });
      continue;
    }
    await fsp.mkdir(path.dirname(item.out), { recursive: true });
    await runProcess(
      ctx,
      [process.execPath, QQ_DECRYPT_CJS, item.src, item.out, keyMapPath],
      ASSETS,
      signal,
    );
    state.lastDecrypt[item.key] = {
      src: item.src,
      mtimeMs: srcStat.mtimeMs,
      size: srcStat.size,
      at: cstTimeFull(Date.now()),
    };
    // 群资料库换新后缓存的群名可能过期，清掉让下次重新解析。
    if (item.key === 'group') state.groupNames = {};
    await saveState(state);
    report.push({ ...item, skipped: false });
  }
  return { keyMapPath, report };
}

export async function walWarning(cfg) {
  const wal = path.join(cfg.dbDir, 'nt_msg.db-wal');
  try {
    const st = await fsp.stat(wal);
    if (st.size > 256 * 1024) {
      return `提示：QQ 的 WAL 暂存文件还有 ${(st.size / 1024 / 1024).toFixed(1)} MB 未归并，最新消息可能不在主库中；若新增数偏少，等一会再试或正常退出 QQ 后重试。`;
    }
  } catch {
    // 没有 WAL，无需提示
  }
  return '';
}

/** ---------- 核心操作 ---------- */

export function cursorSince(state) {
  if (state.cursor && Number.isFinite(Number(state.cursor.lastTs))) {
    return { since: Number(state.cursor.lastTs), fresh: true };
  }
  return { since: 0, fresh: false };
}

function requireCursor(state, gid) {
  const cursor = groupCursor(state, gid);
  if (!cursor) {
    throw new Error(`群 ${gid} 游标尚未设置：请先执行 /wenyou tail ${gid} 500 建立游标`);
  }
  return cursor;
}

function rememberName(state, gid, name) {
  if (!name || String(name) === String(gid)) return;
  state.groupNames = state.groupNames || {};
  state.groupNames[gid] = String(name);
}

/** 检查某群（默认主群）自其游标以来的新增消息。 */
export async function doCheck(ctx, state, cfg, maxRows, signal, group) {
