{"code": "const dir = "D:\\deepseek Harness\\wenyou-opt\\";
const p1 = `/**
 * dsh-wenyou 动作层：/wenyou 子命令与模型工具共用的唯一实现。
 *
 * 每个 action 返回 { ok, text, data }：
 *   - 命令层包成 { kind: 'success' | 'error', text }
 *   - 工具层包成 toolResult(ok, text, data)
 * 这样「命令能做的事」和「AI 能做的事」永远一致，不会再出现两边逻辑漂移。
 */
import path from 'node:path';
import { existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import {
  normalizeGid,
  parseMaxMessages,
  loadState,
  saveState,
  resolveConfig,
  ensureDecrypted,
  doCheck,
  doPull,
  doPullAll,
  runTail,
  quickStats,
  monitoredGroups,
  groupCursor,
  setGroupCursor,
  addMonitoredGroup,
  removeMonitoredGroup,
  resolveGroupNames,
  walWarning,
  buildBriefPrompt,
  cstTime,
} from './core.js';
import {
  statusText,
  checkText,
  pullText,
  configText,
  groupsText,
  tailText,
  pullAllText,
} from './format.js';

export const SETUP_KEYS = {
  qq: 'qq',
  group: 'group',
  db_dir: 'dbDir',
  export_dir: 'exportDir',
  key_map: 'keyMapPath',
  plain_msg_db: 'plainMsgDb',
  plain_group_db: 'plainGroupDb',
  max_messages: 'maxMessages',
  topic: 'topic',
  brief_base: 'briefBase',
  brief_prefix: 'briefPrefix',
};

const ok = (text, data = {}) => ({ ok: true, text, data });
const fail = (text, data = {}) => ({ ok: false, text, data });

/** 一次性准备好 state + 有效配置 + 会话上下文。 */
export async function prepare(agent, signal) {
  const state = await loadState();
  const cfg = await resolveConfig(state, agent);
  return { state, cfg, agent, signal };
}

function userTextMessage(text) {
  return {
    id: randomUUID(),
    role: 'user',
    content: [{ type: 'text', text }],
    source: { kind: 'user' },
  };
}

/** 把后续任务投递给当前会话；投递不了也不算失败，只如实告知。 */
function deliverFollowup(agent, text) {
  if (!agent || typeof agent.followup !== 'function') return false;
  try {
    agent.followup(userTextMessage(text));
    return true;
  } catch {
    return false;
  }
}

/** 解析可选群号参数：缺省=主群；非法则报错而不是静默回落。 */
function pickGroup(cfg, raw) {
  if (raw === undefined || raw === null || raw === '') return { gid: cfg.group };
  const gid = normalizeGid(raw);
  if (gid == null) return { error: \`群号非法：\${raw}\` };
  return { gid };
}

/** ---------- 只读动作 ---------- */

export async function actionStatus(ctx, s) {
  const { state, cfg, signal } = s;
  const quick = existsSync(cfg.plainMsgDb) ? await quickStats(ctx, cfg, state, signal) : null;
  const names = await resolveGroupNames(ctx, cfg, state, [cfg.group], signal);
  const groups = monitoredGroups(state).map(({ gid }) => {
    const c = groupCursor(state, gid);
    return { group: gid, groupName: names[gid] || '', cursor: c ? { lastTs: c.lastTs, lastAt: c.lastAt } : null };
  });
  return ok(statusText(state, cfg, quick, names[cfg.group] || ''), {
    config: {
      qq: cfg.qq,
      group: cfg.group,
      dbDir: cfg.dbDir,
      exportDir: cfg.exportDir,
      plainMsgDb: cfg.plainMsgDb,
      maxMessages: cfg.maxMessages,
