const p2 = `
/** 导出某群最近 n 条并建立游标（顺带把该群纳入监测，幂等不会重复追加）。 */
export async function actionTail(ctx, s, args = {}) {
  const { state, cfg, signal } = s;
  const gid = normalizeGid(args.group);
  const n = Number(args.n);
  if (gid == null || !Number.isFinite(n) || n < 1) {
    return fail('用法：/wenyou tail <群号> <条数（如 500）>');
  }
  const names = await resolveGroupNames(ctx, cfg, state, [gid], signal);
  const added = addMonitoredGroup(state, gid, names[gid] || '');
  if (added.added) await saveState(state);
  await ensureDecrypted(ctx, state, cfg, !!args.force, signal);
  const outJsonl = path.join(cfg.exportDir, \`msgs_尾巴_\${gid}.jsonl\`);
  const outTxt = path.join(cfg.exportDir, \`chatlog_尾巴_\${gid}.txt\`);
  const result = await runTail(ctx, cfg, gid, Math.floor(n), outJsonl, outTxt, signal);
  // 以尾部最新时间戳作为游标；一条都没读到时用当前时间兜底，避免下次从 0 全量扫。
  if (result.count > 0 && result.lastTs != null) {
    await setGroupCursor(state, gid, { lastTs: result.lastTs, lastRowid: result.lastRowid != null ? result.lastRowid : null, lastAt: result.lastAt });
  } else {
    await setGroupCursor(state, gid, { lastTs: Math.floor(Date.now() / 1000), lastRowid: null, lastAt: cstTime(Date.now()) });
  }
  const note = added.added ? '\\n已纳入监测列表；' : '\\n';
  return ok(\`\${tailText(result)}\${note}游标已建立，之后 /wenyou pullall 会把该群并入合订。\`, {
    group: result.group,
    groupName: result.groupName || names[gid] || '',
    count: result.count,
    lastTs: result.lastTs,
    lastAt: result.lastAt,
    outTxt: result.outTxt,
    outJsonl: result.outJsonl,
    monitored: true,
    newlyAdded: added.added,
  });
}

/** 全部受监测群增量导出 + 合订。 */
export async function actionPullAll(ctx, s, args = {}) {
  const { state, cfg, signal } = s;
  const max = parseMaxMessages(args.max_messages, cfg);
  if (max.error) return fail(max.error);
  await ensureDecrypted(ctx, state, cfg, !!args.force, signal);
  const result = await doPullAll(ctx, state, cfg, max.value, signal);
  return ok(pullAllText(result), result);
}

/** ---------- 配置动作 ---------- */

export async function actionAdd(ctx, s, args = {}) {
  const { state, cfg, signal } = s;
  const gid = normalizeGid(args.group);
  if (gid == null) return fail('用法：/wenyou add <群号> [群名称]');
  let name = String(args.name || '').trim();
  if (!name) {
    const names = await resolveGroupNames(ctx, cfg, state, [gid], signal);
    name = names[gid] || '';
  }
  const res = addMonitoredGroup(state, gid, name);
  if (res.reason === 'main') return fail(\`群 \${gid} 就是当前主群，无需重复加入。\`);
  if (res.reason === 'exists') {
    await saveState(state);
    return fail(\`群 \${gid} 已在监测列表中。\`, { group: gid, added: false });
  }
  await saveState(state);
  const allNames = await resolveGroupNames(ctx, cfg, state, monitoredGroups(state).map((g) => g.gid), signal);
  const hint = groupCursor(state, gid)
    ? '（已有游标）'
    : \` → 请执行 /wenyou tail \${gid} 500 建立游标后再使用。\`;
  return ok(\`✅ 已加入监测群 \${gid}\${name ? \`（\${name}）\` : ''}\${hint}\\n\\n\${groupsText(state, allNames)}\`, {
    group: gid,
    groupName: name,
    added: true,
  });
}

export async function actionRemove(ctx, s, args = {}) {
  const { state, cfg, signal } = s;
  const gid = normalizeGid(args.group);
  if (gid == null) return fail('用法：/wenyou remove <群号>');
  const res = removeMonitoredGroup(state, gid);
  if (res.reason === 'main') return fail(\`群 \${gid} 是主群，不能移除；如需换群请 /wenyou setup group <新群号>。\`);
  if (res.reason === 'absent') return fail(\`群 \${gid} 不在监测列表中。\`);
  await saveState(state);
  const names = await resolveGroupNames(ctx, cfg, state, monitoredGroups(state).map((g) => g.gid), signal);
  return ok(\`✅ 已移出监测群 \${gid}（游标与名字缓存一并清除）\\n\\n\${groupsText(state, names)}\`, {
    group: gid,
    removed: true,
  });
}

export async function actionSetup(_ctx, s, args = {}) {
  const { state } = s;
  const key = String(args.key || '').trim();
  if (!key) return ok(configText(state, s.cfg), { config: s.cfg });
  const field = SETUP_KEYS[key];
  if (!field) {
    return fail(\`不支持的配置项：\${key}。支持：\${Object.keys(SETUP_KEYS).join(' / ')}\`);
  }
  const value = String(args.value == null ? '' : args.value).trim();
  if (!value) return fail(\`用法：/wenyou setup \${key} <值>\`);
  if (field === 'group') {
    const gid = normalizeGid(value);
    if (gid == null) return fail(\`群号非法：\${value}\`);
    state.config.group = gid;
  } else if (field === 'maxMessages') {
    const n = Number(value);
    if (!Number.isFinite(n) || n < 1) return fail(\`max_messages 需为正整数：\${value}\`);
    state.config.maxMessages = Math.floor(n);
  } else {
    state.config[field] = value;
  }
  await saveState(state);
  const refreshed = await resolveConfig(state, s.agent);
  return ok(\`✅ 已保存 \${key} = \${value}\\n\\n\${configText(state, refreshed)}\`, {
    key,
    value,
    config: refreshed,
  });
}
`;
const r = await tools.write({ file_path: dir + "actions.part2.js", content: p2 });
return `${r.operation} ${r.path} ${p2.length}`;
