 * 只负责拼字符串——不读盘、不起进程，方便单测与复用。
 */
import { DEFAULT_GROUP, normalizeGid, groupCursor, monitoredGroups } from './core.js';

function cursorLabel(state, gid) {
  const c = groupCursor(state, gid);
  return c && Number.isFinite(Number(c.lastTs)) ? c.lastAt || String(c.lastTs) : '（未建游标）';
}

export function statusText(state, cfg, quick, groupName) {
  const cursorValid = state.cursor && Number.isFinite(Number(state.cursor.lastTs));
  const name = groupName || (quick && quick.groupName) || '';
  const others = monitoredGroups(state).filter((g) => g.gid !== cfg.group);
  const lines = [
    '【文游监测】',
    `群：${cfg.group}${name ? `（${name}）` : ''}`,
    `QQ：${cfg.qq}`,
    `数据目录：${cfg.dbDir}`,
    `导出目录：${cfg.exportDir}`,
    `游标：${cursorValid ? `${state.cursor.lastAt}（ts ${state.cursor.lastTs}）` : '未设置——请先 /wenyou tail <群号> 500 建立游标，避免首次从 0 全量扫描'}`,
    `明文消息库：${cfg.plainMsgDb}`,
    `密钥：${cfg.keyMapPath || '（自动查找，未配置）'}`,
  ];
  if (others.length) {
    lines.push(`其它监测群：${others.map((g) => `${g.gid}${g.name ? `（${g.name}）` : ''} ${cursorLabel(state, g.gid)}`).join('；')}`);
  }
  if (state.lastCheck) {
    const mode = state.lastCheck.mode === 'pullall' ? '合订导出' : '检查';
    lines.push(`上次${mode}：${state.lastCheck.at}，${state.lastCheck.count} 条${state.lastCheck.truncated ? '（已截断）' : ''}`);
  }
  if (quick) {
    lines.push(`快速统计（当前明文库）：${quick.count} 条新增${quick.truncated ? '（已截断）' : ''}${quick.lastAt ? `，最新 ${quick.lastAt}` : ''}`);
    for (const item of quick.sample || []) lines.push(`  · ${item.text}`);
  }
  lines.push('命令：/wenyou check（检查） /wenyou pull（导出） /wenyou brief（简报） /wenyou pullall（合订） /wenyou groups（群列表） /wenyou setup（配置）');
  return lines.join('\n');
}

export function checkText(result, wal) {
  const lines = [
    `【检查结果】群 ${result.group}${result.groupName ? `（${result.groupName}）` : ''} 自游标以来新增 ${result.count} 条消息${result.truncated ? '（超过上限已截断，建议 /wenyou pull）' : ''}`,
  ];
  if (result.count > 0) {
    lines.push(`时间范围：${result.firstAt} ～ ${result.lastAt}`);
    for (const item of result.sample || []) lines.push(`  · ${item.text}`);
  } else {
    lines.push('没有新消息。');
  }
  if (wal) lines.push(wal);
  lines.push('下一步：/wenyou pull 导出，或 /wenyou brief 直接导出并生成简报。');
  return lines.join('\n');
}

export function pullText(result, wal) {
  const lines = [
    result.count > 0
      ? `✅ 已导出群 ${result.group}${result.groupName ? `（${result.groupName}）` : ''} 的 ${result.count} 条新消息（${result.firstAt} ～ ${result.lastAt}）${result.initialPull ? '（首次建立游标）' : ''}`
      : `✅ 群 ${result.group} 没有新消息，未推进游标。`,
  ];
  if (result.count > 0) {
    lines.push(`聊天记录：${result.outTxt}`);
    lines.push(`原始 JSONL：${result.outJsonl}`);
    if (result.truncated) lines.push('⚠ 本次达到导出上限，游标未推进；可用 /wenyou setup max_messages 调大后重试。');
    for (const item of result.sample || []) lines.push(`  · ${item.text}`);
  }
  if (wal) lines.push(wal);
  lines.push('下一步：/wenyou brief 生成局势简报，或直接让我总结。');
  return lines.join('\n');
}

export function configText(state, cfg) {
  return [
    '【当前配置】',
    `qq = ${cfg.qq}`,
    `group = ${cfg.group}`,
    `db_dir = ${cfg.dbDir}`,
    `export_dir = ${cfg.exportDir}`,
    `key_map = ${cfg.keyMapPath || '（自动查找）'}`,
    `plain_msg_db = ${cfg.plainMsgDb}`,
    `plain_group_db = ${cfg.plainGroupDb}`,
    `max_messages = ${cfg.maxMessages}`,
    `topic = ${cfg.topic || '群岛（默认）'}`,
    `brief_base = ${cfg.briefBase || '（自动）'}`,
    `brief_prefix = ${cfg.briefPrefix || '（自动）'}`,
    '',
    '修改示例：/wenyou setup group <QQ_GROUP_001>；/wenyou setup topic 温蒂尼；/wenyou setup brief_prefix 温蒂尼局势_增量_',
  ].join('\n');
}

/** names: { <gid>: '群名' }，缺省用 extraGroups 里登记的名字。 */
export function groupsText(state, names) {
  const main = normalizeGid(state.config.group) || DEFAULT_GROUP;
  const lookup = names || {};
  const lines = ['【受监测群】'];
  let pending = 0;
  for (const { gid, name } of monitoredGroups(state)) {
    const label = lookup[gid] || name || '';
    const cursor = cursorLabel(state, gid);
    if (cursor === '（未建游标）') pending += 1;
    lines.push(`· ${gid}${label ? `（${label}）` : ''} [${gid === main ? '主群' : '额外'} · 游标 ${cursor}]`);
  }
  if (pending) lines.push(`⚠ 有 ${pending} 个群还没有游标，/wenyou pullall 会跳过它们。`);
  lines.push('用法：/wenyou tail <群号> <条数>（建立游标） /wenyou pull <群号> /wenyou pullall（合订导出） /wenyou add <群号> [名称] /wenyou remove <群号>');
  return lines.join('\n');
}

export function tailText(result) {
  const lines = [
    `✅ 已导出群 ${result.group}${result.groupName ? `（${result.groupName}）` : ''} 最近 ${result.count} 条消息（${result.firstAt || '?'} ～ ${result.lastAt || '?'}）。`,
  ];
  if (result.outTxt) lines.push(`聊天记录：${result.outTxt}`);
  if (result.outJsonl) lines.push(`原始 JSONL：${result.outJsonl}`);
  for (const item of result.sample || []) lines.push(`  · ${item.text}`);
  lines.push('提示：这只是逐群独立文件；要把各群按时间合并看，请 /wenyou pullall。');
  return lines.join('\n');
}

export function pullAllText(result) {
  const lines = ['【合订导出】'];
  if (result.combinedTxt) {
    lines.push(`合订聊天记录：${result.combinedTxt}（共 ${result.combinedCount} 行，${result.firstAt || '?'} ～ ${result.lastAt || '?'}）`);
  } else {
    lines.push(`本次没有新消息（合计 ${result.combinedCount || 0} 条），未生成合订文件。`);
  }
  for (const p of result.perGroup || []) {
    lines.push(`  · 群 ${p.gid}（${p.name || ''}）：${p.count} 条${p.truncated ? '（已截断，游标未推进）' : ''}`);
  }
  if (result.pendingGroups && result.pendingGroups.length) {
    lines.push(`⚠ 跳过未建游标的群：${result.pendingGroups.join('、')}（先 /wenyou tail <群号> 500）`);
  }
  lines.push('下一步：读取合订文件即可纵览各群在同一时间轴的局势。');
  return lines.join('\n');
}

