{"code": "const dir = "D:\\deepseek Harness\\wenyou-opt\\";
const content = `/**
 * dsh-wenyou — QQ 文字<QQ_GROUP_NAME_001>（文游）群监测插件。
 *
 * 分层：lib/core.js（状态/子进程/密钥/解密/核心操作）
 *     → lib/actions.js（命令与模型工具共用的动作层）
 *     → lib/format.js（纯文本渲染）
 *     → 本文件（只做注册与参数解析，不含业务逻辑）
 *
 * 命令：/wenyou [status|check|pull|brief|pullall|tail|groups|add|remove|setup|help]
 * 工具：wenyou_status / wenyou_check / wenyou_pull / wenyou_brief /
 *       wenyou_status_all / wenyou_tail / wenyou_pull_all
 */
import { defineTool } from '@deepseek-ai/dsh-tools';
import { errorText } from './core.js';
import { toolResult } from './format.js';
import * as actions from './actions.js';

export const name = 'dsh-wenyou';
export const inject = ['subprocess', 'commands', 'tools'];

/** 子命令中文别名。 */
const ALIASES = {
  状态: 'status',
  检查: 'check',
  导出: 'pull',
  简报: 'brief',
  设置: 'setup',
  配置: 'setup',
  合订: 'pullall',
  多群: 'pullall',
  尾巴: 'tail',
  群: 'groups',
  列表: 'groups',
  加群: 'add',
  删群: 'remove',
  移除: 'remove',
  帮助: 'help',
};

/** setup 配置项中文别名。 */
const SETUP_ALIASES = {
  群号: 'group',
  主群: 'group',
  主题: 'topic',
  上限: 'max_messages',
  导出目录: 'export_dir',
  数据目录: 'db_dir',
};

const HELP = [
  '【/wenyou 用法】',
  '  /wenyou                 查看状态（配置、游标、当前明文库新增统计）',
  '  /wenyou check [群号]     检查自游标以来的新增消息（必要时先解密）',
  '  /wenyou pull [群号]      增量导出 chatlog + jsonl 并推进游标',
  '  /wenyou brief [群号]     先导出，再把「写增量简报」交给当前会话',
  '  /wenyou pullall         全部监测群增量导出并按时间合订成一份',
  '  /wenyou groups          查看受监测群与各自游标',
  '  /wenyou tail <群号> <条数>  导出最近 n 条并建立游标（自动纳入监测）',
  '  /wenyou add <群号> [名称]   纳入监测（仍需 tail 建游标）',
  '  /wenyou remove <群号>       移出监测（清掉其游标与名字缓存）',
  '  /wenyou setup [项 值]       查看/修改配置',
  '中文别名：状态 检查 导出 简报 合订 群 尾巴 加群 删群 设置 帮助',
].join('\\n');

/** 子命令 → 动作。返回 null 表示未知子命令。 */
function dispatch(ctx, s, head, parts) {
  switch (head) {
    case 'status':
    case 's':
      return actions.actionStatus(ctx, s);
    case 'groups':
    case 'g':
      return actions.actionGroups(ctx, s);
    case 'check':
    case 'c':
      return actions.actionCheck(ctx, s, { group: parts[1] });
    case 'pull':
    case 'p':
      return actions.actionPull(ctx, s, { group: parts[1] });
    case 'brief':
    case 'b':
      return actions.actionBrief(ctx, s, { group: parts[1] });
    case 'pullall':
    case 'pa':
      return actions.actionPullAll(ctx, s, {});
    case 'tail':
    case 't':
      return actions.actionTail(ctx, s, { group: parts[1], n: parts[2] });
    case 'add':
      return actions.actionAdd(ctx, s, { group: parts[1], name: parts.slice(2).join(' ') });
    case 'remove':
    case 'rm':
      return actions.actionRemove(ctx, s, { group: parts[1] });
    case 'setup':
      return actions.actionSetup(ctx, s, {
        key: parts[1] ? (SETUP_ALIASES[parts[1]] || parts[1]) : '',
        value: parts.slice(2).join(' '),
      });
    case 'help':
    case 'h':
      return Promise.resolve({ ok: true, text: HELP, data: {} });
    default:
      return null;
  }
}

/** 注册一个模型工具：统一 output/render/错误处理，只描述参数与要跑的动作。 */
function registerTool(ctx, spec) {
  ctx.tools.register(defineTool({
    name: spec.name,
    description: spec.description,
    parameters: spec.parameters || {},
    ...(spec.timeoutMs ? { timeoutMs: spec.timeoutMs } : {}),
    output: {
      schema: { type: 'object', additionalProperties: true },
      render: (_args, value) => [{ type: 'text', text: String(value && value.summary) }],
    },
    execute: async (args, exec) => {
      try {
        const s = await actions.prepare(exec.agent, exec.signal);
        const res = await spec.run(ctx, s, args || {});
        return toolResult(res.ok, res.text, res.data);
      } catch (err) {
        return toolResult(false, \`\${spec.name} 失败：\${errorText(err)}\`);
      }
    },
  }));
}

const FORCE_PARAM = { type: 'boolean', description: '强制重新解密 QQ 数据库（默认 false，源文件未变化时复用已解密库）' };
const GROUP_PARAM = { type: 'integer', description: '群号（默认主群 <QQ_GROUP_001>）' };
const MAX_PARAM = { type: 'integer', description: '本次最多导出的消息数（默认 20000，上限 200000）' };

export function apply(ctx) {
  // ---------- /wenyou 命令 ----------
  ctx.commands.register({
    name: 'wenyou',
    description: 'QQ 文游群监测：状态 / check / pull / brief / pullall / tail / groups / add / remove / setup',
    handler: async (invocation) => {
      try {
        const parts = String(invocation.rawInput || '').trim().split(/\\s+/).filter(Boolean);
        const head = ALIASES[parts[0]] || parts[0] || 'status';
        const s = await actions.prepare(invocation.agent, invocation.signal);
        const pending = dispatch(ctx, s, head, parts);
        if (!pending) {
          return { kind: 'error', text: \`未知子命令：\${head}\\n\\n\${HELP}\` };
        }
        const res = await pending;
        return { kind: res.ok ? 'success' : 'error', text: res.text };
      } catch (err) {
        return { kind: 'error', text: \`文游插件出错：\${errorText(err)}\` };
      }
    },
  });

  // ---------- 模型工具 ----------
