{"code": "const base = "D:\\deepseek Harness\\wenyou-opt\\smoke\\";
const test = `import { existsSync, mkdirSync, mkdtempSync, openSync, closeSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { spawn as nodeSpawn } from 'node:child_process';
import os from 'node:os';

const ROOT = 'D:\\\\deepseek Harness\\\\wenyou-opt\\\\smoke';
const TMP = join(ROOT, 'tmp');
mkdirSync(TMP, { recursive: true });
// 把 DSH_HOME 指到临时目录：测试只读真实明文库，绝不动真实 state.json
process.env.DSH_HOME = join(TMP, 'dsh-home');
const STORE = join(process.env.DSH_HOME, 'storages', 'dsh-wenyou');
mkdirSync(STORE, { recursive: true });
const REAL_PLAIN = 'C:\\\\Users\\\\<USER>\\\\.dsh\\\\storages\\\\dsh-wenyou\\\\plain';
const EXPORT = join(TMP, 'export');
mkdirSync(EXPORT, { recursive: true });

// 故意造一份“脏”历史状态：群号是字符串、extraGroups 有重复且混入主群
const legacy = {
  version: 1,
  config: {
    qq: '<QQ_ACCOUNT_001>',
    group: '<QQ_GROUP_001>',
    exportDir: EXPORT,
    plainMsgDb: join(REAL_PLAIN, 'nt_msg_plain.db'),
    plainGroupDb: join(REAL_PLAIN, 'group_info_plain.db'),
    maxMessages: '20000',
    extraGroups: [
      { gid: <QQ_GROUP_003>, name: '' },
      { gid: '<QQ_GROUP_003>', name: '重复条目' },
      { gid: <QQ_GROUP_001>, name: '主群被误加' },
      { gid: <QQ_GROUP_002>, name: '<CONTACT_001>' },
      { gid: 'x', name: '非法' },
    ],
  },
  cursor: { lastTs: 1787061222, lastRowid: null, lastAt: '08-18 21:53:42' },
  groups: { <QQ_GROUP_003>: { lastTs: 1787058523, lastRowid: null, lastAt: '08-18 21:08:43' }, <QQ_GROUP_002>: { lastTs: 1787060261, lastRowid: null, lastAt: '08-18 21:37:41' } },
};
writeFileSync(join(STORE, 'state.json'), JSON.stringify(legacy, null, 2), 'utf8');

const core = await import('./core.js');
const fmt = await import('./format.js');
const actions = await import('./actions.js');
const plugin = await import('./index.js');

const fails = [];
const check = (label, cond, extra) => {
  if (cond) console.log('  ok  ' + label);
  else { fails.push(label); console.log('  FAIL ' + label + (extra ? ' :: ' + extra : '')); }
};

// ---- 1. 状态归一化 ----
console.log('[1] state normalization');
const st = await core.loadState();
check('group 归一化为 number', st.config.group === <QQ_GROUP_001>, typeof st.config.group);
check('maxMessages 归一化为 number', st.config.maxMessages === 20000, typeof st.config.maxMessages);
check('extraGroups 去重/剔除主群/剔除非法 => 2 条', st.config.extraGroups.length === 2, JSON.stringify(st.config.extraGroups));
const gids = core.monitoredGroups(st).map((g) => g.gid);
check('monitoredGroups = 主群 + 2', gids.length === 3 && gids[0] === <QQ_GROUP_001>, JSON.stringify(gids));
check('主群游标可读', !!core.groupCursor(st, <QQ_GROUP_001>));
check('字符串群号也能取到游标', !!core.groupCursor(st, '<QQ_GROUP_003>'));

// ---- 2. 增删幂等 ----
console.log('[2] add/remove idempotency');
check('重复 add 返回 exists', core.addMonitoredGroup(st, <QQ_GROUP_003>, '').reason === 'exists');
check('add 主群被拒', core.addMonitoredGroup(st, <QQ_GROUP_001>, '').reason === 'main');
check('add 非法群号被拒', core.addMonitoredGroup(st, 'abc', '').reason === 'invalid');
const add1 = core.addMonitoredGroup(st, <QQ_ACCOUNT_008>, '新群');
check('新群加入成功', add1.added === true && st.config.extraGroups.length === 3);
check('remove 主群被拒', core.removeMonitoredGroup(st, <QQ_GROUP_001>).reason === 'main');
check('remove 新群成功', core.removeMonitoredGroup(st, <QQ_ACCOUNT_008>).removed === true && st.config.extraGroups.length === 2);

// ---- 3. 参数校验 ----
console.log('[3] parseMaxMessages');
const cfgStub = { maxMessages: 20000 };
check('缺省用配置值', core.parseMaxMessages(undefined, cfgStub).value === 20000);
check('合法值取整', core.parseMaxMessages('123.9', cfgStub).value === 123);
check('0 报错', !!core.parseMaxMessages(0, cfgStub).error);
check('超上限报错', !!core.parseMaxMessages(200001, cfgStub).error);

// ---- 4. 渲染 ----
console.log('[4] renderers');
const gtext = fmt.groupsText(st, { <QQ_GROUP_001>: '文明·不朽<QQ_GROUP_NAME_001>群' });
check('groupsText 三行群', (gtext.match(/^· /gm) || []).length === 3, gtext);
check('groupsText 有 remove 提示', gtext.includes('/wenyou remove'));
const stext = fmt.statusText(st, { ...legacy.config, group: <QQ_GROUP_001>, dbDir: 'D:\\\\x', exportDir: EXPORT, keyMapPath: '' }, null, '文明·不朽<QQ_GROUP_NAME_001>群');
check('statusText 含其它监测群', stext.includes('其它监测群'), stext);

// ---- 5. 插件注册 ----
console.log('[5] plugin registration');
const registered = { commands: [], tools: [] };
plugin.apply({
  commands: { register: (c) => registered.commands.push(c) },
  tools: { register: (t) => registered.tools.push(t) },
});
check('注册 1 个命令 wenyou', registered.commands.length === 1 && registered.commands[0].name === 'wenyou');
const toolNames = registered.tools.map((t) => t.name).sort();
const expected = ['wenyou_brief', 'wenyou_check', 'wenyou_pull', 'wenyou_pull_all', 'wenyou_status', 'wenyou_status_all', 'wenyou_tail'].sort();
check('注册 7 个工具且名字不变', JSON.stringify(toolNames) === JSON.stringify(expected), toolNames.join(','));
check('每个工具都有 execute/render', registered.tools.every((t) => typeof t.execute === 'function' && typeof t.output.render === 'function'));

// ---- 6. 真实子进程：names 子命令 + 缓存 ----
console.log('[6] group names via python (real db)');
function makeCtx() {
  let spawns = 0;
  return {
    spawns: () => spawns,
    subprocess: {
      async resolveExecutable(name) {
        if (name && existsSync(name)) return name;
        throw new Error('not found: ' + name);
      },
      spawn({ argv, cwd }) {
        spawns += 1;
        const dir = mkdtempSync(join(TMP, 'proc-'));
        const outPath = join(dir, 'out.txt');
        const errPath = join(dir, 'err.txt');
        const of = openSync(outPath, 'w');
        const ef = openSync(errPath, 'w');
        const child = nodeSpawn(argv[0], argv.slice(1), { cwd, stdio: ['ignore', of, ef] });
        const done = new Promise((resolve, reject) => {
          child.on('error', reject);
          child.on('close', (code) => { closeSync(of); closeSync(ef); resolve({ exitCode: code }); });
        });
        const read = (p) => { try { return readFileSync(p, 'utf8'); } catch { return ''; } };
        return {
          done,
          collected: { stdout: { readFrom: () => ({ text: read(outPath) }) }, stderr: { readFrom: () => ({ text: read(errPath) }) } },
          terminate: async () => {},
        };
      },
    },
  };
}
const ctx = makeCtx();
const s = await actions.prepare(null, undefined);
check('resolveConfig 保留自定义明文库', s.cfg.plainGroupDb.endsWith('group_info_plain.db'));
let t0 = Date.now();
const r1 = await actions.actionGroups(ctx, s);
const ms1 = Date.now() - t0;
check('actionGroups 成功', r1.ok === true);
check('三个群都拿到中文名', r1.data.groups.every((g) => g.groupName && !/^\\d+$/.test(g.groupName)), JSON.stringify(r1.data.groups));
check('只起了 1 个子进程', ctx.spawns() === 1, 'spawns=' + ctx.spawns());
console.log('  · 首次解析耗时 ' + ms1 + 'ms');
t0 = Date.now();
const r2 = await actions.actionGroups(ctx, s);
const ms2 = Date.now() - t0;
check('二次走缓存不再起进程', ctx.spawns() === 1, 'spawns=' + ctx.spawns());
check('缓存后名字仍在', r2.data.groups.every((g) => !!g.groupName));
console.log('  · 命中缓存耗时 ' + ms2 + 'ms');

// ---- 7. status 在明文库缺失时也能渲染 ----
