block.arguments:
{"code": "const dir = "D:\\deepseek Harness\\wenyou-opt\\backup-new\\";
const p1 = `/**
 * dsh-backup — 一键备份 DeepSeek Harness 用户数据。
 *
 * 备份 ~/.dsh（会话、配置、技能、凭据、插件配置），排除可重装的
 * node_modules，生成 sha256 校验和，自动轮换旧备份；支持定时自动备份。
 *
 * - \`/backup\`            立即备份到 <桌面>/dsh-backups/
 * - \`/backup list\`       列出已有备份 + 自动备份状态
 * - \`/backup auto\`       查询自动备份状态
 * - \`/backup auto <N>\`   每 N 小时自动备份（1~720；<24h 保留 3 份，否则 7 份）
 * - \`/backup auto off\`   关闭自动备份
 * - \`/backup --keep N\`   覆盖保留份数（1~50）
 * - \`backup_dsh\` 模型工具：mode=backup|list|auto，keep/hours 可选
 *
 * 自动备份配置持久化到 ~/.dsh/storages/dsh-backup/state.json，DSH 重启后恢复。
 *
 * 打包策略：优先用 tar（Linux/macOS 自带；Windows 10+ 的 system32\\tar.exe 即 bsdtar），
 * 产出真正的 .tar.gz 并保留目录结构；只有在完全找不到 tar 时才退回 PowerShell
 * Compress-Archive 打整目录 .zip（此时无法排除 node_modules，会在结果里明说）。
 *
 * 安全说明：备份包含明文凭据（.credentials.yaml、qq-bridge/config.json），
 * 非 Windows 上收紧为 600 仅本人可读写；请勿将备份目录同步到不受信位置。
 */
import { defineTool } from '@deepseek-ai/dsh-tools';
import { promises as fsp, createReadStream } from 'node:fs';
import { createHash } from 'node:crypto';
import { pipeline } from 'node:stream/promises';
import path from 'node:path';
import os from 'node:os';
import { spawn as nodeSpawn } from 'node:child_process';

export const name = 'dsh-backup';
export const inject = ['subprocess', 'fs', 'commands', 'timer', 'tools'];

const DEFAULT_KEEP = 7;
const MAX_KEEP = 50;
const MAX_AUTO_HOURS = 720;
const ARCHIVE_SUFFIXES = ['.tar.gz', '.zip'];

export function apply(ctx) {
  // ---------- 持久化状态 ----------
  const DATA_DIR = path.join(process.env.DSH_HOME || path.join(os.homedir(), '.dsh'), 'storages', 'dsh-backup');
  const STATE_FILE = path.join(DATA_DIR, 'state.json');

  const errText = (err) => String(err && err.message ? err.message : err);
  const pad2 = (n) => String(n).padStart(2, '0');

  function stampNow() {
    const d = new Date();
    return \`\${d.getFullYear()}\${pad2(d.getMonth() + 1)}\${pad2(d.getDate())}-\${pad2(d.getHours())}\${pad2(d.getMinutes())}\${pad2(d.getSeconds())}\${pad2(d.getMilliseconds())}\`;
  }

  function clampKeep(value) {
    const n = Number(value);
    if (!Number.isFinite(n) || n < 1) return DEFAULT_KEEP;
    return Math.min(MAX_KEEP, Math.floor(n));
  }

  async function writeJsonAtomic(file, value) {
    const tmp = \`\${file}.tmp\`;
    await fsp.writeFile(tmp, JSON.stringify(value, null, 2), 'utf8');
    try {
      await fsp.rename(tmp, file);
    } catch {
      await fsp.rm(file, { force: true });
      await fsp.rename(tmp, file);
    }
  }

  async function readState() {
    try {
      const raw = JSON.parse(await fsp.readFile(STATE_FILE, 'utf8'));
      return {
        autoHours: Number(raw.autoHours) > 0 ? Number(raw.autoHours) : 0,
        lastAuto: typeof raw.lastAuto === 'string' ? raw.lastAuto : null,
        lastError: typeof raw.lastError === 'string' ? raw.lastError : null,
      };
    } catch {
      return { autoHours: 0, lastAuto: null, lastError: null };
    }
  }

  async function saveState(state) {
    await fsp.mkdir(DATA_DIR, { recursive: true });
    await writeJsonAtomic(STATE_FILE, state);
  }

  // ---------- 工具函数 ----------
  async function spawnRun(argv, cwd, signal) {
    const proc = ctx.subprocess.spawn({
      argv,
      cwd,
      graceMs: 5000,
      signal,
      stdio: {
        stdin: 'ignore',
        stdout: { maxBytes: 8192, spill: { maxBytes: 1 << 20 } },
        stderr: { maxBytes: 8192, spill: { maxBytes: 1 << 20 } },
      },
    });
    const outcome = await proc.done;
    const out = proc.collected.stdout?.readFrom(0).text ?? '';
    const err = proc.collected.stderr?.readFrom(0).text ?? '';
    if (outcome.exitCode !== 0) {
      throw new Error(\`命令失败 exit=\${outcome.exitCode}: \${err || out}\`);
    }
    return { out, err };
  }

  /**
