  async function runAutoBackup() {
    if (autoRunning) {
      console.warn('[dsh-backup] 上一次自动备份还在进行，跳过本次触发');
      return;
    }
    autoRunning = true;
    try {
      const r = await doBackup(autoHours >= 24 ? DEFAULT_KEEP : 3);
      lastAuto = path.basename(r.path);
      await persistAuto(autoHours, null);
      console.log(`[dsh-backup] 自动备份完成: ${r.path} (${mb(r.size)}, sha ${r.sha.slice(0, 12)}…)`);
    } catch (err) {
      const msg = errText(err);
      lastError = msg;
      await persistAuto(autoHours, msg);
      console.error(`[dsh-backup] 自动备份失败: ${msg}`);
    } finally {
      autoRunning = false;
    }
  }

  // ---------- /backup 命令 ----------
  ctx.commands.register({
    name: 'backup',
    description: '备份 DSH 数据到 <桌面>/dsh-backups；子命令: list | auto [N小时|off|status] | [--keep N]',
    handler: async (invocation) => {
      await loadPersistedState();
      const input = String(invocation.rawInput || '').trim();
      try {
        const parts = input.split(/\s+/).filter(Boolean);
        const head = parts[0] || '';

        if (head === 'list' || head === '列表') {
          const all = await listBackups();
          const { root } = paths();
          const text = all.length
            ? `已有备份 (${all.length} 份) @ ${root}:\n${all.map((n) => `  ${n}`).join('\n')}\n\n${autoSummary()}`
            : `暂无备份（目录 ${root}）。输入 /backup 执行首次备份。\n\n${autoSummary()}`;
          return { kind: 'success', text };
        }

        if (head === 'auto' || head === '自动') {
          const arg = parts[1];
          if (!arg || arg === 'status') return { kind: 'success', text: autoSummary() };
          if (arg === 'off' || arg === '0' || arg === '关') {
            disableAuto();
            await persistAuto(0, null);
            return { kind: 'success', text: '自动备份已关闭。' };
          }
          const h = Number(arg);
          if (!Number.isFinite(h) || h < 1 || h > MAX_AUTO_HOURS) {
            return { kind: 'error', text: `小时数需为 1~${MAX_AUTO_HOURS} 之间的数字（如 /backup auto 12）` };
          }
          enableAuto(Math.floor(h));
          await persistAuto(Math.floor(h), null);
          return { kind: 'success', text: `✅ 自动备份已开启：每 ${Math.floor(h)} 小时执行一次（保留 ${h >= 24 ? DEFAULT_KEEP : 3} 份）。\n${autoSummary()}` };
        }

        if (head && head !== '--keep' && !/^--keep=/.test(head)) {
          return { kind: 'error', text: `未知子命令：${head}。可用：/backup（立即备份） /backup list /backup auto [N|off] /backup --keep N` };
        }

        const m = input.match(/--keep[\s=]+(\d+)/);
        const r = await doBackup(m ? Number(m[1]) : undefined, invocation.signal);
        return { kind: 'success', text: `${backupText(r)}\n  ${autoSummary()}` };
      } catch (err) {
        return { kind: 'error', text: `备份失败: ${errText(err)}` };
      }
    },
  });

  // ---------- backup_dsh 模型工具 ----------
  ctx.tools.register(defineTool({
    name: 'backup_dsh',
    description: '备份或列出 DSH 用户数据（~/.dsh 的会话、配置、技能、凭据）。mode=backup 立即备份（可选 keep 指定保留份数，默认 7）；mode=list 列出已有备份与自动备份状态；mode=auto 设置自动备份（hours 为间隔小时数，0=关闭，缺省返回当前状态）。注意：备份包含明文凭据，请勿将备份目录同步到不受信位置。',
    parameters: {
      mode: { type: 'string', required: true, enum: ['backup', 'list', 'auto'], description: 'backup=执行备份，list=列出备份与自动备份状态，auto=设置自动备份' },
      keep: { type: 'number', description: '保留的备份份数（默认 7，上限 50）' },
      hours: { type: 'number', description: '自动备份间隔小时数（mode=auto 时使用；0=关闭；缺省=查询状态）' },
    },
    output: {
      schema: { type: 'object', additionalProperties: true },
      render: (_args, value) => [{ type: 'text', text: String(value.summary) }],
    },
    execute: async (args, exec) => {
      await loadPersistedState();
      const mode = args && args.mode ? args.mode : 'backup';
      const signal = exec && exec.signal ? exec.signal : undefined;
      try {
        if (mode === 'list') {
          const all = await listBackups();
          return { ok: true, count: all.length, backups: all, root: paths().root, summary: `已有 ${all.length} 份备份 @ ${paths().root}:\n${all.join('\n') || '（无）'}\n\n${autoSummary()}` };
        }
        if (mode === 'auto') {
          const h = args && args.hours !== undefined && args.hours !== null ? Number(args.hours) : null;
          if (h === null) return { ok: true, autoHours, summary: autoSummary() };
          if (h === 0) {
            disableAuto();
            await persistAuto(0, null);
            return { ok: true, autoHours: 0, summary: '自动备份已关闭。' };
          }
          if (!Number.isFinite(h) || h < 1 || h > MAX_AUTO_HOURS) return { ok: false, summary: `hours 需为 1~${MAX_AUTO_HOURS}` };
          enableAuto(Math.floor(h));
          await persistAuto(Math.floor(h), null);
          return { ok: true, autoHours: Math.floor(h), summary: `自动备份已开启：每 ${Math.floor(h)} 小时一次。\n${autoSummary()}` };
        }
        if (mode !== 'backup') {
          return { ok: false, summary: `不支持的 mode：${mode}（可用 backup / list / auto）` };
        }
        const r = await doBackup(args && args.keep ? args.keep : undefined, signal);
        return {
          ok: true,
          path: r.path,
          sha: r.sha,
          size: r.size,
          format: r.format,
          excluded: r.excluded,
          keep: r.keep,
          rotated: r.stale,
          rotateErrors: r.rotateErrors,
          summary: `备份完成: ${r.path}\n大小: ${mb(r.size)}（${r.format}）\nsha256: ${r.sha}\n轮换删除 ${r.stale} 份（保留 ${r.keep} 份）${r.excluded ? '' : '\n⚠ 未找到 tar，已退回 zip 整目录打包（含 node_modules）'}${r.rotateErrors.length ? `\n⚠ 删除失败：${r.rotateErrors.join('；')}` : ''}`,
        };
      } catch (err) {
        return { ok: false, summary: `备份失败: ${errText(err)}` };
      }
    },
  }));
}

