const test = `import { mkdirSync, writeFileSync, existsSync, readFileSync, rmSync, mkdtempSync, openSync, closeSync, statSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { spawn as nodeSpawn } from 'node:child_process';
import { createHash } from 'node:crypto';

const ROOT = 'D:\\\\deepseek Harness\\\\wenyou-opt\\\\backup-new';
const TMP = join(ROOT, 'tmp');
rmSync(TMP, { recursive: true, force: true });
const HOME = join(TMP, 'home');
const DSH = join(HOME, '.dsh');
// 假的 ~/.dsh：嵌套同名文件 + 应被排除的 node_modules / .system
mkdirSync(join(DSH, 'sessions', 'a'), { recursive: true });
mkdirSync(join(DSH, 'nested', 'deep'), { recursive: true });
mkdirSync(join(DSH, 'storages', 'x', 'node_modules'), { recursive: true });
mkdirSync(join(DSH, '.system'), { recursive: true });
mkdirSync(join(HOME, 'Desktop'), { recursive: true });
writeFileSync(join(DSH, 'sessions', 'a', 'state.json'), '{"who":"sessions"}');
writeFileSync(join(DSH, 'nested', 'deep', 'state.json'), '{"who":"nested"}');
writeFileSync(join(DSH, 'settings.yaml'), 'agent: test\\n');
writeFileSync(join(DSH, 'storages', 'x', 'node_modules', 'junk.js'), 'junk');
writeFileSync(join(DSH, '.system', 'y.txt'), 'system');
process.env.DSH_HOME = DSH;

const mod = await import('./index.js');
const fails = [];
const check = (label, cond, extra) => {
  if (cond) console.log('  ok  ' + label);
  else { fails.push(label); console.log('  FAIL ' + label + (extra ? ' :: ' + extra : '')); }
};

function runCapture(argv, cwd) {
  const d = mkdtempSync(join(TMP, 'proc-'));
  const o = join(d, 'o.txt'); const e = join(d, 'e.txt');
  const of = openSync(o, 'w'); const ef = openSync(e, 'w');
  const child = nodeSpawn(argv[0], argv.slice(1), { cwd, stdio: ['ignore', of, ef] });
  return new Promise((resolve, reject) => {
    child.on('error', reject);
    child.on('close', (code) => {
      closeSync(of); closeSync(ef);
      resolve({ code, out: readFileSync(o, 'utf8'), err: readFileSync(e, 'utf8') });
    });
  });
}

const env = new Map([['HOME', { value: HOME }], ['USERPROFILE', { value: HOME }], ['DSH_HOME', { value: DSH }]]);
const reg = { commands: [], tools: [], intervals: [] };
const ctx = {
  get: (k) => (k === 'launchEnvironment' ? { get: (key) => env.get(key) } : undefined),
  interval: (fn, ms) => { reg.intervals.push({ fn, ms }); return () => { reg.intervals = reg.intervals.filter((i) => i.fn !== fn); }; },
  commands: { register: (c) => reg.commands.push(c) },
  tools: { register: (t) => reg.tools.push(t) },
  fs: {},
  subprocess: {
    async resolveExecutable(nm) {
      const known = { tar: 'C:\\\\WINDOWS\\\\system32\\\\tar.exe' };
      if (known[nm] && existsSync(known[nm])) return known[nm];
      throw new Error('not found: ' + nm);
    },
    spawn({ argv, cwd }) {
      const d = mkdtempSync(join(TMP, 'sp-'));
      const o = join(d, 'o.txt'); const e = join(d, 'e.txt');
      const of = openSync(o, 'w'); const ef = openSync(e, 'w');
      const child = nodeSpawn(argv[0], argv.slice(1), { cwd, stdio: ['ignore', of, ef] });
      const done = new Promise((resolve, reject) => {
        child.on('error', reject);
        child.on('close', (code) => { closeSync(of); closeSync(ef); resolve({ exitCode: code }); });
      });
      const rd = (p) => { try { return readFileSync(p, 'utf8'); } catch { return ''; } };
      return { done, collected: { stdout: { readFrom: () => ({ text: rd(o) }) }, stderr: { readFrom: () => ({ text: rd(e) }) } }, terminate: async () => {} };
    },
  },
};

mod.apply(ctx);
console.log('[1] registration');
check('注册 /backup 命令', reg.commands.length === 1 && reg.commands[0].name === 'backup');
check('注册 backup_dsh 工具', reg.tools.length === 1 && reg.tools[0].name === 'backup_dsh');
const tool = reg.tools[0];
const cmd = reg.commands[0];

console.log('[2] 真实备份（tar 路径）');
const r1 = await tool.execute({ mode: 'backup', keep: 2 }, {});
check('备份成功', r1.ok === true, r1.summary);
check('产物是 .tar.gz', typeof r1.path === 'string' && r1.path.endsWith('.tar.gz'), r1.path);
check('声明已排除 node_modules', r1.excluded === true);
check('文件存在且非空', !!r1.path && existsSync(r1.path) && statSync(r1.path).size > 0);
const shaSide = r1.path + '.sha256';
check('sha256 旁文件存在', existsSync(shaSide));
const recomputed = createHash('sha256').update(readFileSync(r1.path)).digest('hex');
check('sha256 与文件实际一致', recomputed === r1.sha, r1.sha + ' vs ' + recomputed);
check('旁文件内容含 sha 与文件名', existsSync(shaSide) && readFileSync(shaSide, 'utf8').includes(r1.sha));

console.log('[3] 压缩包内容（结构 + 排除）');
const listing = await runCapture(['C:\\\\WINDOWS\\\\system32\\\\tar.exe', '-tzf', r1.path], TMP);
const entries = listing.out.split(/\\r?\\n/).filter(Boolean);
check('保留嵌套结构 sessions/a/state.json', entries.some((e) => e.replace(/\\\\/g, '/').endsWith('.dsh/sessions/a/state.json')), entries.slice(0, 12).join(' | '));
check('保留嵌套结构 nested/deep/state.json', entries.some((e) => e.replace(/\\\\/g, '/').endsWith('.dsh/nested/deep/state.json')));
check('两个同名 state.json 都在（不再压平撞名）', entries.filter((e) => e.endsWith('state.json')).length === 2, String(entries.filter((e) => e.endsWith('state.json')).length));
check('排除 node_modules', !entries.some((e) => e.includes('node_modules')));
check('排除 .system', !entries.some((e) => e.includes('.system')));

console.log('[4] 轮换（旧实现在 Windows 因缺少 rm 直接失败）');
await new Promise((r) => setTimeout(r, 60));
const r2 = await tool.execute({ mode: 'backup', keep: 2 }, {});
await new Promise((r) => setTimeout(r, 60));
const r3 = await tool.execute({ mode: 'backup', keep: 2 }, {});
check('第二、三次备份成功', r2.ok === true && r3.ok === true, (r2.summary || '') + ' / ' + (r3.summary || ''));
const left = readdirSync(join(HOME, 'Desktop', 'dsh-backups')).filter((n) => n.endsWith('.tar.gz'));
check('keep=2 只留 2 份', left.length === 2, left.join(','));
check('轮换无错误', Array.isArray(r3.rotateErrors) && r3.rotateErrors.length === 0, JSON.stringify(r3.rotateErrors));
check('sha 旁文件同步清理', readdirSync(join(HOME, 'Desktop', 'dsh-backups')).filter((n) => n.endsWith('.sha256')).length === 2);

console.log('[5] list / auto');
const rl = await tool.execute({ mode: 'list' }, {});
check('list 返回 2 份', rl.ok === true && rl.count === 2, JSON.stringify(rl.count));
const ra = await tool.execute({ mode: 'auto', hours: 5 }, {});
check('auto 5 小时开启', ra.ok === true && ra.autoHours === 5 && reg.intervals.length === 1, ra.summary);
const rst = await tool.execute({ mode: 'auto' }, {});
check('auto 查询含 5 小时', rst.summary.includes('每 5 小时'), rst.summary);
const roff = await tool.execute({ mode: 'auto', hours: 0 }, {});
check('auto 0 关闭并清定时器', roff.ok === true && reg.intervals.length === 0);
check('状态已持久化到 DSH_HOME', existsSync(join(DSH, 'storages', 'dsh-backup', 'state.json')));
const rbad = await tool.execute({ mode: 'auto', hours: 9999 }, {});
check('非法 hours 被拒', rbad.ok === false);
const rmode = await tool.execute({ mode: 'nope' }, {});
check('未知 mode 被拒', rmode.ok === false, rmode.summary);

console.log('[6] 命令层');
const c1 = await cmd.handler({ rawInput: 'list', signal: undefined });
check('/backup list 成功', c1.kind === 'success' && c1.text.includes('已有备份'), c1.text.slice(0, 80));
const c2 = await cmd.handler({ rawInput: '瞎写', signal: undefined });
check('/backup 未知子命令报错而不是误备份', c2.kind === 'error', c2.text);
const c3 = await cmd.handler({ rawInput: '--keep 1', signal: undefined });
check('/backup --keep 1 成功', c3.kind === 'success' && c3.text.includes('备份完成'), c3.text.slice(0, 120));
const left2 = readdirSync(join(HOME, 'Desktop', 'dsh-backups')).filter((n) => n.endsWith('.tar.gz'));
check('--keep 1 只留 1 份', left2.length === 1, left2.join(','));

console.log('');
console.log(fails.length ? 'FAILED: ' + fails.length + ' :: ' + fails.join(' | ') : 'ALL PASS');
process.exit(fails.length ? 1 : 0);
`;
const w = await tools.write({ file_path: dir + "test.mjs", content: test });
const r = await tools.pwsh({ command: `cd '${dir}'; node test.mjs`, description: "Run dsh-backup end-to-end test", timeoutMs: 240000 });
return r.kind === "foreground" ? `exit=${r.exitCode}\n${r.stdout.text}\n--stderr--\n${r.stderr.text.slice(0, 800)}` : "bg";
", "description": "Write and run dsh-backup end-to-end test"}

