import { mkdirSync, writeFileSync, existsSync, readFileSync, rmSync, mkdtempSync, openSync, closeSync, statSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { spawn as nodeSpawn } from 'node:child_process';
import { createHash } from 'node:crypto';

const ROOT = 'D:\\deepseek Harness\\wenyou-opt\\backup-new';
const TMP = join(ROOT, 'tmp');
rmSync(TMP, { recursive: true, force: true });
const HOME = join(TMP, 'home');
const DSH = join(HOME, '.dsh');
// 假的 ~/.dsh：嵌套同名文件 + 应被排除的 node_modules / .system
mkdirSync(join(DSH, 'sessions', 'a'), { recursive: true });
mkdirSync(join(DSH, 'nested', 'deep'), { recursive: true });
mkdirSync(join(DSH, 'storages', 'x', 'node_modules'), { recursive: true });
mkdirSync(join(DSH, '.system'), { recursive: true });
mkdirSync(join(HOME, 'Desktop'), { recursive: true });
writeFileSync(join(DSH, 'sessions', 'a', 'state.json'), '{"who":"sessions"}');
writeFileSync(join(DSH, 'nested', 'deep', 'state.json'), '{"who":"nested"}');
writeFileSync(join(DSH, 'settings.yaml'), 'agent: test\n');
writeFileSync(join(DSH, 'storages', 'x', 'node_modules', 'junk.js'), 'junk');
writeFileSync(join(DSH, '.system', 'y.txt'), 'system');
process.env.DSH_HOME = DSH;

