const fails = [];
const check = (label, cond, extra) => {
  if (cond) console.log('  ok  ' + label);
  else { fails.push(label); console.log('  FAIL ' + label + (extra ? ' :: ' + extra : '')); }
};

function runCapture(argv, cwd) {
  const d = mkdtempSync(join(TMP, 'proc-'));
  const o = join(d, 'o.txt'); const e = join(d, 'e.txt');
  const of = openSync(o, 'w'); const ef = openSync(e, 'w');
  const child = nodeSpawn(argv[0], argv.slice(1), { cwd, stdio: ['ignore', of, ef] });
  return new Promise((resolve, reject) => {
    child.on('error', reject);
    child.on('close', (code) => {
      closeSync(of); closeSync(ef);
      resolve({ code, out: readFileSync(o, 'utf8'), err: readFileSync(e, 'utf8') });
