--- lib/index.js (68 lines) ---
1	// dsh-approve-desktop host bundle (hand-authored ESM, no external deps).
2	export const name = 'dsh-approve-desktop';
3	export const inject = ['approval'];
4	const DEFAULT_PORT = 40441;
5	const DEFAULT_RETRIES = 2;
6	const RETRY_DELAY_MS = 5000;
7	const REQUEST_TIMEOUT_MS = 120000;
8	function hostName() {
9	  const p = Number(process.env.DSH_APPROVE_PORT) || DEFAULT_PORT;
10	  return `http://127.0.0.1:${p}`;
11	}
12	function sleep(ms) {
13	  return new Promise((resolve) => setTimeout(resolve, ms));
14	}
15	async function askDesktopOnce(info) {
16	  const controller = new AbortController();
17	  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
18	  try {
19	    const res = await fetch(`${hostName()}/approval`, {
20	      method: 'POST',
21	      headers: { 'content-type': 'application/json' },
22	      body: JSON.stringify(info),
23	      signal: controller.signal,
24	    });
25	    if (!res.ok) throw new Error(`desktop approval HTTP ${res.status}`);
26	    return await res.json();
27	  } finally {
28	    clearTimeout(timeout);
29	  }
30	}
31	async function askDesktop(info) {
32	  const retries = Math.max(0, Number(process.env.DSH_APPROVE_RETRIES) || DEFAULT_RETRIES);
33	  let lastError;
34	  for (let attempt = 0; attempt <= retries; attempt += 1) {
35	    if (attempt > 0) {
36	      console.info(`[dsh-approve-desktop] 重试第 ${attempt}/${retries} 次...`);
37	      await sleep(RETRY_DELAY_MS);
38	    }
39	    try {
40	      const result = await askDesktopOnce(info);
41	      if (attempt > 0) console.info(`[dsh-approve-desktop] 重试成功`);
42	      return result;
43	    } catch (err) {
44	      lastError = err;
45	      console.warn(`[dsh-approve-desktop] 第 ${attempt + 1} 次请求失败: ${err?.message ?? err}`);
46	    }
47	  }
48	  throw lastError;
49	}
50	export function apply(ctx) {
51	  return ctx.on('approval/request', async (req) => {
52	    const info = {
53	      toolName: req?.toolName ?? '工具',
54	      reason: req?.reason ?? '需要人工授权',
55	      callId: req?.callId ?? null,
56	    };
57	    console.info(`[dsh-approve-desktop] approval requested: ${info.toolName} — ${info.reason}`);
58	    try {
59	      const decision = await askDesktop(info);
60	      const outcome = decision?.allowed === true ? 'allowed-once' : 'rejected';
61	      console.info(`[dsh-approve-desktop] user decision: ${outcome}`);
62	      return outcome;
63	    } catch (err) {
64	      console.error(`[dsh-approve-desktop] desktop bridge unavailable (${err?.message}); failing closed -> rejected`);
65	      return 'rejected';
66	    }
67	  });
68	}

