{"code": "const js = `// dsh-approve-desktop host bundle (hand-authored ESM, no external deps).
//
// 在 \`approval/request\` 瀑布上注册 answerer：把审批请求 POST 给本机桌面审批服务
// （默认 127.0.0.1:40441 → desktop-shell/approve-server.mjs），等用户在中文确认窗里
// 选允许/拒绝，再把结果回给 DSH。
//
// v0.2.0 关键语义（平台 ApprovalOutcome 共四种，旧版只会返回前两种）：
//   allowed-once  用户点了「允许」
//   rejected      用户点了「拒绝」（含确认窗 90s 超时自动拒绝）
//   cancelled     请求被撤回（req.signal 中断，例如本轮对话被取消）——不再白等 120 秒
//   unavailable   桥不可达/无应答（服务没起、HTTP 异常、响应无法解析、我方超时）
// 四种都不会放行操作；区分它们是为了让上层与日志能分清「用户说不」和「根本没人应答」。
export const name = 'dsh-approve-desktop'
export const inject = ['approval']

const VERSION = '0.2.0'
const DEFAULT_PORT = 40441
/** 连接抖动重试次数（不含第一次）。桌面服务刚启动时可能还没监听。 */
const DEFAULT_RETRIES = 2
/** 重试间隔 ms（原 5000 太长：审批是人在等，缩短到 1.5s）。 */
const DEFAULT_RETRY_DELAY_MS = 1500
/** 单次请求超时 ms：必须长于确认窗自身的 90s 超时，否则我方先超时会留下孤儿弹窗。 */
const DEFAULT_REQUEST_TIMEOUT_MS = 120000

/** 读环境变量整数：显式 0 也要生效（旧版 \`Number(x) || 默认值\` 会把 0 当假值吞掉）。 */
function envInt(key, fallback, { min = 0 } = {}) {
  const raw = process.env[key]
  if (raw === undefined || raw === '') return fallback
  const n = Number(raw)
  if (!Number.isFinite(n) || n < min) {
    console.warn(\`[dsh-approve-desktop] 环境变量 \${key}=\${raw} 非法，回退到 \${fallback}\`)
    return fallback
  }
  return Math.floor(n)
}

function hostName() {
  return \`http://127.0.0.1:\${envInt('DSH_APPROVE_PORT', DEFAULT_PORT, { min: 1 })}\`
}

function sleep(ms, signal) {
  return new Promise((resolve) => {
    const timer = setTimeout(resolve, ms)
    if (signal) {
      const onAbort = () => { clearTimeout(timer); resolve() }
      if (signal.aborted) onAbort()
      else signal.addEventListener('abort', onAbort, { once: true })
    }
  })
}

/** 带类别的桥接错误：类别决定「要不要重试」与「返回哪种 outcome」。 */
class BridgeError extends Error {
  constructor(kind, message) {
    super(message)
    this.name = 'BridgeError'
    this.kind = kind   // 'cancelled' | 'timeout' | 'connect' | 'http' | 'parse'
  }
}

/** 只有连接层失败才值得重试；用户没答、请求被撤回、协议出错都不该重试。 */
function isRetryable(kind) {
  return kind === 'connect'
}

async function askDesktopOnce(info, outerSignal, timeoutMs) {
  const controller = new AbortController()
  let cancelled = false
  let timedOut = false
  const onOuterAbort = () => { cancelled = true; controller.abort() }
  if (outerSignal) {
    if (outerSignal.aborted) onOuterAbort()
    else outerSignal.addEventListener('abort', onOuterAbort, { once: true })
  }
  const timer = setTimeout(() => { timedOut = true; controller.abort() }, timeoutMs)
  try {
    const res = await fetch(\`\${hostName()}/approval\`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(info),
      signal: controller.signal,
    })
    if (!res.ok) throw new BridgeError('http', \`desktop approval HTTP \${res.status}\`)
    try {
      return await res.json()
    } catch (err) {
      throw new BridgeError('parse', \`响应不是合法 JSON: \${err?.message ?? err}\`)
    }
  } catch (err) {
    if (err instanceof BridgeError) throw err
    if (cancelled) throw new BridgeError('cancelled', '审批请求已被撤回')
    if (timedOut) throw new BridgeError('timeout', \`等待桌面确认窗超过 \${timeoutMs}ms\`)
    throw new BridgeError('connect', \`桌面审批服务不可达: \${err?.message ?? err}\`)
  } finally {
    clearTimeout(timer)
    if (outerSignal) outerSignal.removeEventListener?.('abort', onOuterAbort)
  }
}

async function askDesktop(info, outerSignal) {
  const retries = envInt('DSH_APPROVE_RETRIES', DEFAULT_RETRIES)
  const retryDelayMs = envInt('DSH_APPROVE_RETRY_DELAY_MS', DEFAULT_RETRY_DELAY_MS)
  const timeoutMs = envInt('DSH_APPROVE_TIMEOUT_MS', DEFAULT_REQUEST_TIMEOUT_MS, { min: 1000 })
  let lastError = new BridgeError('connect', '未发起任何请求')
  for (let attempt = 0; attempt <= retries; attempt += 1) {
    if (outerSignal?.aborted) throw new BridgeError('cancelled', '审批请求已被撤回')
    if (attempt > 0) {
      console.info(\`[dsh-approve-desktop] \${info.tag} 连接失败，重试 \${attempt}/\${retries}…\`)
      await sleep(retryDelayMs, outerSignal)
      if (outerSignal?.aborted) throw new BridgeError('cancelled', '审批请求已被撤回')
    }
    try {
      const result = await askDesktopOnce(info, outerSignal, timeoutMs)
      if (attempt > 0) console.info(\`[dsh-approve-desktop] \${info.tag} 重试成功\`)
      return result
    } catch (err) {
      lastError = err
      const kind = err?.kind ?? 'connect'
      console.warn(\`[dsh-approve-desktop] \${info.tag} 第 \${attempt + 1} 次失败(\${kind}): \${err?.message ?? err}\`)
