process.env.DSH_APPROVE_PORT = String(s.port);
const p1 = h({ toolName: 't', callId: 'dup' });
const p2 = h({ toolName: 't', callId: 'dup' });
setTimeout(() => go(), 200);
const [o1, o2] = await Promise.all([p1, p2]);
check('两次都 allowed-once', o1 === 'allowed-once' && o2 === 'allowed-once', o1 + '/' + o2);
check('只弹一次(hits=1)', s.hits.n === 1, s.hits.n);
await s.close();

console.log('[6] 连接失败可重试（服务迟到 250ms 才起）');
process.env.DSH_APPROVE_RETRIES = '2';
process.env.DSH_APPROVE_RETRY_DELAY_MS = '200';
