const port = tmp.port;
await tmp.close();
process.env.DSH_APPROVE_PORT = String(port);
const late = h({ toolName: 't', callId: 'c6' });
let srv2 = null;
setTimeout(() => { srv2 = http.createServer((q, r) => { r.writeHead(200, { 'content-type': 'application/json' }); r.end('{"allowed":true}'); }); srv2.listen(port, '127.0.0.1'); }, 250);
out = await late;
check('重试后成功 allowed-once', out === 'allowed-once', out);
if (srv2) await new Promise((r) => srv2.close(r));

console.log('');
console.log(fails.length ? 'FAILED: ' + fails.length + ' :: ' + fails.join(' | ') : 'ALL PASS');
process.exit(fails.length ? 1 : 0);

