const head = await tools.read({ file_path: f, limit: 8 });
console.log(head.lines.map(l => `${l.number}\t${l.text}`).join("\n"));
const arch = await tools.pwsh({
  command: `$s = 'D:\\deepseek Harness\\desktop-shell\\.state'
$dst = Join-Path $s '_archive-20260821'
New-Item -ItemType Directory -Force -Path $dst | Out-Null
$pat = @('dlg-out*','dlg-err*','dlg-ui.txt','apprv-out.txt','apprv-err.txt','tray-test-*','approve-win.png','approve-print.png','wendini-monitor.log','question-test*.json','restart_result.txt')
$moved = 0
foreach ($p in $pat) { Get-ChildItem -Path $s -Filter $p -File -ErrorAction SilentlyContinue | ForEach-Object { Move-Item $_.FullName -Destination $dst -Force; $moved++ } }
"moved=$moved"
Get-ChildItem $s -File | ForEach-Object { $_.Name } | Sort-Object`,
  description: "Archive stale .state debug artifacts",
});
return "--- .state after archive ---\n" + (arch.kind === "foreground" ? arch.stdout.text : "");
", "description": "Read build script header and archive debug leftovers"}

