{"code": "const r = await tools.pwsh({
  command: `'=== 关机/重启相关事件（最近 20 条）==='
Get-WinEvent -FilterHashtable @{LogName='System'; Id=@(41,1074,6006,6008,6005,6013,109)} -MaxEvents 20 -ErrorAction SilentlyContinue |
  Select-Object TimeCreated, Id, ProviderName, @{n='Msg';e={ ($_.Message -replace "\\r?\\n",' ').Substring(0, [Math]::Min(190, $_.Message.Length)) }} |
  Format-List | Out-String -Width 220`,
  description: "Query shutdown and reboot event log",
  timeoutMs: 120000,
});
return r.kind === "foreground" ? r.stdout.text.slice(0, 4000) + r.stderr.text.slice(0, 300) : "bg";
", "description": "Query Windows event log for reboot cause"}

