{"code": "const r = await tools.pwsh({
  command: `$e = Get-WinEvent -FilterHashtable @{LogName='System'; Id=1074} -MaxEvents 3 -ErrorAction SilentlyContinue
foreach ($x in $e) {
  '--- ' + $x.TimeCreated.ToString('yyyy-MM-dd HH:mm:ss') + ' ---'
  $i = 0
  foreach ($p in $x.Properties) { '  [' + $i + '] ' + $p.Value; $i++ }
}
'=== 最近的 Windows Update 安装事件 ==='
Get-WinEvent -FilterHashtable @{LogName='System'; ProviderName='Microsoft-Windows-WindowsUpdateClient'} -MaxEvents 5 -ErrorAction SilentlyContinue |
  ForEach-Object { $_.TimeCreated.ToString('MM-dd HH:mm') + ' Id=' + $_.Id + ' ' + (($_.Message -replace "\\r?\\n",' ')) } |
  ForEach-Object { $_.Substring(0, [Math]::Min(160, $_.Length)) }`,
  description: "Identify who initiated the restart",
  timeoutMs: 120000,
});
return r.kind === "foreground" ? r.stdout.text.slice(0, 3000) + "\n--stderr--\n" + r.stderr.text.slice(0, 300) : "bg";
", "description": "Extract 1074 event details and update history"}

