{"code": "const r = await tools.pwsh({
  command: `'=== dsh web 服务启动时间（它之后落盘的代码才需要再重启）==='
Get-Process -Id 20164 -ErrorAction SilentlyContinue | ForEach-Object { 'dsh web PID 20164 启动=' + $_.StartTime.ToString('HH:mm:ss') }
'=== 各插件产物最后修改时间 + 版本 ==='
$items = @(
  @{n='dsh-wenyou';        p='C:\\Users\\<USER>\\.dsh\\plugins-src\\dsh-wenyou\\lib\\index.js'},
  @{n='dsh-backup';        p='C:\\Users\\<USER>\\.dsh\\plugins-src\\dsh-backup\\lib\\index.js'},
  @{n='dsh-approve-desktop'; p='C:\\Users\\<USER>\\.dsh\\plugins-src\\dsh-approve-desktop\\lib\\index.js'},
  @{n='dsh-notification';  p='C:\\Users\\<USER>\\.dsh\\plugins-src\\dsh-notification\\lib\\client.js'},
  @{n='dsh-enter-approve'; p='C:\\Users\\<USER>\\.dsh\\plugins-src\\dsh-enter-approve\\lib\\client.js'}
)
foreach ($i in $items) {
  $ver = (Get-Content (Join-Path (Split-Path (Split-Path $i.p -Parent) -Parent) 'package.json') -Raw | ConvertFrom-Json).version
  $t = (Get-Item $i.p).LastWriteTime.ToString('MM-dd HH:mm:ss')
  $i.n.PadRight(22) + 'v' + $ver.PadRight(8) + '产物改于 ' + $t
}
'=== desktop-shell 关键文件 ==='
foreach ($n in @('main.mjs','config.mjs','approve-server.mjs','notifier.mjs','doctor.mjs','build-native.ps1','架构与维护.md')) {
  $p = Join-Path 'D:\\deepseek Harness\\desktop-shell' $n
  $n.PadRight(22) + (Get-Item $p).LastWriteTime.ToString('MM-dd HH:mm:ss') + '  ' + (Get-Item $p).Length + 'B'
}`,
  description: "Verify versions and whether running service loaded new code",
  timeoutMs: 90000,
});
return r.kind === "foreground" ? r.stdout.text : "bg";
", "description": "Verify plugin versions and load timing"}

