{"code": "const r = await tools.pwsh({
  command: `'=== 当前时间 / 系统启动 ==='
Get-Date -Format 'HH:mm:ss'
'=== 关键进程（对比重启前：DshDesktop 18220 / dsh web 20164 / shell 18724 / tray 20140 / approve 6928）==='
foreach ($n in @('DshDesktop','node','pwsh')) {
  Get-Process $n -ErrorAction SilentlyContinue | ForEach-Object {
    $path = try { $_.Path } catch { '' }
    $_.ProcessName.PadRight(12) + 'PID=' + $_.Id.ToString().PadRight(7) + '启动=' + $_.StartTime.ToString('HH:mm:ss') + '  ' + $path
  }
}
'=== 运行中的窗口是从哪个 dist 加载的 ==='
Get-Process DshDesktop -ErrorAction SilentlyContinue | ForEach-Object { 'PID ' + $_.Id + ' → ' + $_.Path }
'=== dist* 目录现状 ==='
Get-ChildItem 'D:\\deepseek Harness\\desktop-shell' -Directory -Filter 'dist*' | ForEach-Object { $_.Name }
'=== state.json ==='
Get-Content 'D:\\deepseek Harness\\desktop-shell\\.state\\state.json' -Raw`,
  description: "Check whether restart and consolidation took effect",
  timeoutMs: 120000,
});
return r.kind === "foreground" ? r.stdout.text.slice(0, 3000) : "bg";
", "description": "Verify restart and dist consolidation status"}

