    """临时阅读：取某群最近 n 条。倒序 rowid 扫描，遇损坏页自动缩小批次并跳过。"""
    out = []
    last = None
    batch = 2000
    guard = 0
    skipped = 0
    while len(out) < n:
        guard += 1
        if guard > 4_000_000:
            log("peek 扫描超过保护上限，停止")
            break
        try:
            if last is None:
                rows = conn.execute(
                    f'SELECT rowid, "{TCOL}", "{GCOL}", "{SCOL}", "{BCOL}" '
                    f"FROM group_msg_table ORDER BY rowid DESC LIMIT ?", (batch,)).fetchall()
            else:
                rows = conn.execute(
                    f'SELECT rowid, "{TCOL}", "{GCOL}", "{SCOL}", "{BCOL}" '
                    f"FROM group_msg_table WHERE rowid < ? ORDER BY rowid DESC LIMIT ?",
                    (last, batch)).fetchall()
        except Exception:
            safe_rollback(conn)
            skipped += 1
