 * 用法：/wenyou peek <群号> [条数] [起始时间]；起始时间支持 unix 时间戳或「MM-DD HH:MM」/「MM-DD」。
 */
export async function actionPeek(ctx, s, args = {}) {
  const { state, cfg, signal } = s;
  const gid = normalizeGid(args.group);
  if (gid == null) return fail('用法：/wenyou peek <群号> [条数（默认 50）] [起始时间（可选，如 08-18 或 08-18 13:00 或 unix 时间戳）]');
  const nRaw = args.n == null ? 50 : Number(args.n);
  const n = Number.isFinite(nRaw) && nRaw >= 1 ? Math.min(500, Math.floor(nRaw)) : 50;

  // 解析起始时间（北京时间）：
  let since = 0;
  if (args.since != null && String(args.since).trim() !== '') {
    const raw = String(args.since).trim();
    if (/^\\d{9,10}$/.test(raw)) {
      since = Number(raw);
    } else {
      const m = raw.match(/^(\\d{1,2})-(\\d{1,2})(?:\\s+(\\d{1,2}):(\\d{2}))?$/);
      if (!m) return fail(\`起始时间格式不对：\${raw}。请用 unix 时间戳、\`08-18\` 或 \`08-18 13:00\`（北京时间）。\`);
      const now = new Date();
      const year = now.getFullYear();
      const dt = new Date(Date.UTC(year, Number(m[1]) - 1, Number(m[2]), m[3] ? Number(m[3]) : 0, m[4] ? Number(m[4]) : 0, 0) - 8 * 3600 * 1000);
      since = Math.floor(dt.getTime() / 1000);
      if (since > Date.now() / 1000) return fail(\`起始时间在未来：\${raw}。\`);
    }
  }

  await ensureDecrypted(ctx, state, cfg, !!args.force, signal);
