  const stamp = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
  const outTxt = path.join(cfg.exportDir, \`chatlog_临时阅读_\${gid}_\${stamp}.txt\`);
  const result = await runPeek(ctx, cfg, gid, n, since, outTxt, signal);
  if (result.ok === false) {
    return fail(result.detail || \`群 \${gid} 暂时读不到消息。\`, { group: gid, error: result.error || 'corrupt' });
  }
  const header = [
    \`【临时阅读】群 \${gid}（\${result.groupName || ''}）\`,
    \`共 \${result.count} 条\${result.fallback ? '（⚠ 尾部页不可读，已按可读区域返回）' : ''}\${since ? \`，自 \${result.firstAt || '?'} 起\` : ''}\`,
  ];
  const body = (result.sample || []).map((item) => \`  · \${item.text}\`).join('\\n');
  const footer = [
    '',
    \`完整记录：\${outTxt}\`,
    '说明：只读不改——没有建游标、没有加入监测，之后 /wenyou pullall 不会带上这个群。',
  ];
  return ok([...header, body, ...footer].join('\\n'), {
    group: result.group,
    groupName: result.groupName,
    count: result.count,
    since,
    firstAt: result.firstAt,
    lastAt: result.lastAt,
    outTxt: result.outTxt || outTxt,
    fallback: !!result.fallback,
    sample: result.sample || [],
    temporary: true,
  });
}

