{"code": "const script = `<#
  dsh 内核升级 0.1.0-rc.7 → 0.1.0-rc.8（无人值守版）
  ------------------------------------------------------------------
  流程：前置检查 → 快照 → 停服务 → 替换版本 → npm 安装(npmmirror) → 重打
        message-edit/version 补丁(E-010) → 起服务 → 轮询验证 → 写结果日志。
  用法：pwsh -NoProfile -ExecutionPolicy Bypass -File D:\\deepseek Harness\\upgrade_kernel_rc8.ps1
  结果：D:\\deepseek Harness\\upgrade_rc8_result.log
#>
$ErrorActionPreference = 'Continue'
$result = 'D:\\deepseek Harness\\upgrade_rc8_result.log'
function Log($m) {
  $line = (Get-Date -Format 'HH:mm:ss') + '  ' + $m
  Write-Host $line
  Add-Content -Path $result -Value $line -Encoding utf8
}
Set-Content -Path $result -Value ('=== 内核升级 rc.7→rc.8 开始 ' + (Get-Date) + ' ===') -Encoding utf8

$installAnchor = 'C:\\Users\\<USER>\\Documents\\ChatGPT\\日常事项\\DeepSeekHarness\\pkg\\package'
$shellDir = 'D:\\deepseek Harness\\desktop-shell'
$npmCache = 'D:\\deepseek Harness\\.npm-cache-tmp'
$registry = 'https://registry.npmmirror.com'

# ---------- 0. 前置检查 ----------
Log '[0/6] 前置检查'
foreach ($p in @($installAnchor, (Join-Path $installAnchor 'package.json'), (Join-Path $shellDir 'main.mjs'))) {
  if (-not (Test-Path $p)) { Log "FAIL 缺少: $p"; exit 1 }
}
$cur = (Get-Content (Join-Path $installAnchor 'package.json') -Raw | ConvertFrom-Json).version
Log "当前内核版本: $cur"
if ($cur -ne '0.1.0-rc.7') { Log "FAIL 预期 rc.7，实际 $cur——中止，请人工检查"; exit 1 }

# ---------- 1. 快照 ----------
Log '[1/6] 快照关键文件'
$bk = 'D:\\deepseek Harness\\backups\\kernel_rc8_auto_' + (Get-Date -Format 'yyyyMMdd-HHmmss')
New-Item -ItemType Directory -Force -Path $bk | Out-Null
Copy-Item (Join-Path $installAnchor 'package.json'), (Join-Path $installAnchor 'package-lock.json'), 'C:\\Users\\<USER>\\.dsh\\settings.yaml' $bk -Force
$snap = (Get-ChildItem (Join-Path $installAnchor 'node_modules\\@deepseek-ai') -Directory | Where-Object { $_.Name -match '^dsh' } | Measure-Object).Count
Log "快照 → $bk（含 dsh-* 包数: $snap）"

# ---------- 2. 停服务 ----------
Log '[2/6] 停止 dsh 服务（桌面壳 --stop）'
Push-Location $shellDir
& node main.mjs --stop 2>&1 | ForEach-Object { Log "stop: $_" }
Start-Sleep -Seconds 4
$still = & netstat -ano | Select-String ':3080' | Select-String 'LISTENING'
if ($still) { Log 'WARN 3080 仍被监听，按端口清理'; $still | ForEach-Object { $pid3080 = ($_.ToString().Trim() -split '\s+')[-1]; & taskkill /F /T /PID $pid3080 2>&1 | ForEach-Object { Log $_ } }; Start-Sleep -Seconds 2 }
Log '服务已停'

# ---------- 3. 替换版本号 ----------
Log '[3/6] 替换 package.json 版本 0.1.0-rc.7 → 0.1.0-rc.8'
$pkgPath = Join-Path $installAnchor 'package.json'
$txt = Get-Content $pkgPath -Raw -Encoding utf8
$txt2 = $txt -replace '0\.1\.0-rc\.7', '0.1.0-rc.8'
Set-Content -Path $pkgPath -Value $txt2 -Encoding utf8NoBOM -NoNewline
$new = (Get-Content $pkgPath -Raw | ConvertFrom-Json).version
Log "package.json 版本 → $new"

# ---------- 4. npm 安装 ----------
Log '[4/6] npm install（npmmirror，cache=自定义）'
Push-Location $installAnchor
$env:npm_config_cache = $npmCache
$env:npm_config_registry = $registry
& npm install 2>&1 | ForEach-Object { $s = "$_"; if ($s -match 'error|ERR|warn deprecated' ) { Log $s } }
$installed = (Get-Content (Join-Path $installAnchor 'node_modules\\@deepseek-ai\\dsh\\package.json') -Raw | ConvertFrom-Json).version
Log "安装后内核版本: $installed"
if ($installed -ne '0.1.0-rc.8') { Log 'FAIL npm 安装后版本不对——中止，可回滚快照'; exit 1 }

# ---------- 5. 重打 E-010 补丁 ----------
Log '[5/6] 检查并重打 message-edit/version 补丁（E-010）'
$targets = @(
  (Join-Path $installAnchor 'node_modules\\@deepseek-ai\\dsh-session\\lib\\types\\known-event-types.js'),
  (Join-Path $installAnchor 'node_modules\\@deepseek-ai\\dsh-session\\lib\\index.js')
)
foreach ($t in $targets) {
  if (-not (Test-Path $t)) { Log "SKIP（不存在）: $t"; continue }
  $c = Get-Content $t -Raw -Encoding utf8
  if ($c -match 'message-edit/version') { Log "OK 已含补丁: $t"; continue }
  $insert = "'message-edit/version',"
  if ($c -match "KNOWN_SESSION_EVENT_TYPES = \\[") {
    $c2 = $c -replace "(KNOWN_SESSION_EVENT_TYPES = \\[)", "`$1`n  $insert"
  } elseif ($c -match "'[a-z-]+/[a-z-]+',") {
    $c2 = $c -replace "('[a-z-]+/[a-z-]+',)", "$insert`n  `$1"
  } else {
    Log "WARN 找不到插入点，跳过: $t"; continue
  }
  Set-Content -Path $t -Value $c2 -Encoding utf8NoBOM -NoNewline
  Log "已打补丁: $t"
}

# ---------- 6. 起服务 + 验证 ----------
Log '[6/6] 启动服务并验证'
Push-Location $shellDir
Start-Process -FilePath 'node' -ArgumentList 'main.mjs' -WorkingDirectory $shellDir -WindowStyle Hidden
$ok = $false
for ($i = 0; $i -lt 60; $i++) {
  Start-Sleep -Seconds 3
  try {
    $resp = & node -e "fetch('http://127.0.0.1:3080').then(r=>{console.log(r.status);process.exit(r.status===200?0:1)}).catch(()=>process.exit(2))" 2>$null
    if ($LASTEXITCODE -eq 0) { Log "验证通过: 3080 返回 200（第 $($i*3) 秒）"; $ok = $true; break }
  } catch { }
}
if (-not $ok) { Log 'FAIL 3080 未在 180 秒内就绪——升级可能失败，请查 server.log / 回滚快照' }
Log ('=== 完成 ' + (Get-Date) + ' 最终版本: ' + $installed + ' ===')
`;
