{"code": "const f = "C:\\Users\\<USER>\\AppData\\Local\\Temp\\dshupgrade\\upgrade.ps1";
const r1 = await tools.edit({
  file_path: f,
  old_string: `if ($cur -ne '0.1.0-rc.7') { Log 'FAIL 预期 rc.7'; exit 1 }`,
  new_string: `if ($cur -ne '0.1.0-rc.8') { Log \"FAIL 预期 rc.8（当前 $cur）\"; exit 1 }`,
});
