  file_path: f,
  old_string: `Log '[3/7] 替换版本 0.1.0-rc.7 → 0.1.1-rc.2'
$pkgPath = Join-Path $installAnchor 'package.json'
$txt = Get-Content $pkgPath -Raw -Encoding utf8
Set-Content -Path $pkgPath -Value $txt.Replace('0.1.0-rc.7', '0.1.1-rc.2') -Encoding utf8NoBOM -NoNewline`,
  new_string: `Log '[3/7] 替换版本 0.1.0-rc.8 → 0.1.1-rc.2'
$pkgPath = Join-Path $installAnchor 'package.json'
$txt = Get-Content $pkgPath -Raw -Encoding utf8
Set-Content -Path $pkgPath -Value $txt.Replace('0.1.0-rc.8', '0.1.1-rc.2') -Encoding utf8NoBOM -NoNewline`,
});
const r3 = await tools.edit({
  file_path: f,
  old_string: `Set-Content -Path $result -Value ('=== 内核升级 rc.7→0.1.1-rc.2 开始 ' + (Get-Date) + ' ===') -Encoding utf8`,
  new_string: `Set-Content -Path $result -Value ('=== 内核升级 rc.8→0.1.1-rc.2 开始 ' + (Get-Date) + ' ===') -Encoding utf8`,
});
const chk = await tools.pwsh({
  command: `$errs = $null; [void][System.Management.Automation.Language.Parser]::ParseFile('C:\\Users\\<USER>\\AppData\\Local\\Temp\\dshupgrade\\upgrade.ps1', [ref]$null, [ref]$errs); '语法错误数=' + $errs.Count`,
  description: "Fix upgrade script for rc.8 baseline and check",
  timeoutMs: 90000,
});
return `${[r1, r2, r3].map(x => x.path.split("\\").pop()).join(", ")} patched\n${chk.kind === "foreground" ? chk.stdout.text : ""}`;
", "description": "Fix upgrade script baseline to rc.8"}

