    /** 强制重新解密 QQ 数据库（默认 false，源文件未变化时复用已解密库） */
    force?: boolean;
    /** 群号（默认主群 <QQ_GROUP_001>） */
    group?: number;
    /** 本次最多导出的消息数（默认 20000，上限 200000） */
    max_messages?: number;
  } & Record<string, JsonValue>;
