=== restore_hanhua.ps1 是否存在 ===
存在: True
--- 内容 ---
# restore_hanhua.ps1
# 重新应用 DSH Web UI 的三处中文汉化补丁：
#   1. 推理档位名称（Off/Low/High/Max -> 关闭/低/高/最大）
#   2. 斜杠命令描述（/goal /permission /plan /compact /feedback /export）
#   3. 权限预设名称与说明（read-only / workspace-write / danger-full-access）
# 幂等：已打过补丁会跳过。更新内核后 node_modules 被覆盖时，重跑本脚本即可。
$ErrorActionPreference = 'Stop'

$pkg = 'C:\Users\<USER>\Documents\ChatGPT\日常事项\DeepSeekHarness\pkg\package\node_modules\@deepseek-ai'
$profilePatch = Join-Path $env:USERPROFILE '.dsh\profiles\web\cordis.patch.yml'

function Apply-Replacement {
  param(
    [string]$Path,
    [string]$Old,
    [string]$New,
    [string]$Marker
  )
  $raw = [System.IO.File]::ReadAllText($Path)
  if ($raw.Contains($Marker)) {
    Write-Output "SKIP (already patched): $Path"
    return
  }
  if (-not $raw.Contains($Old)) {
    throw "Pattern not found in $Path`n---`n$Old"
  }
  $raw = $raw.Replace($Old, $New)
  [System.IO.File]::WriteAllText($Path, $raw, [System.Text.UTF8Encoding]::new($false))
  Write-Output "PATCHED: $Path"
}

# ---------- 1. 推理档位 ----------
$modelSelect = Join-Path $pkg 'dsh-client-ui-model-selection\lib\client.js'
$oldImport = @'
		let _deepseek_ai_dsh_client_ui_primitives = require("@deepseek-ai/dsh-client-ui-primitives");
		//#region lib/types/client/directory.js
'@
$newImport = @'
		let _deepseek_ai_dsh_client_ui_primitives = require("@deepseek-ai/dsh-client-ui-primitives");
		/** Translate known reasoning effort ids for the zh UI. */
		function effortName(t, effort) {
			if (t("menu.effort") !== "推理等级") return effort.name;
			const labels = { off: "关闭", low: "低", medium: "中", high: "高", max: "最大" };
			return labels[effort.id] ?? effort.name;
		}
		//#region lib/types/client/directory.js
'@
Apply-Replacement -Path $modelSelect -Old $oldImport -New $newImport -Marker 'function effortName(t, effort)'

$oldEffortLabel = '			const effortLabel = reasoning === void 0 ? void 0 : effectiveEffort === void 0 ? t("effort.providerDefault") : reasoning.efforts.find((level) => level.id === effectiveEffort)?.name ?? effectiveEffort;'
$newEffortLabel = '			const effortLabel = reasoning === void 0 ? void 0 : effectiveEffort === void 0 ? t("effort.providerDefault") : (reasoning.efforts.find((level) => level.id === effectiveEffort) === void 0 ? effectiveEffort : effortName(t, reasoning.efforts.find((level) => level.id === effectiveEffort)));'
Apply-Replacement -Path $modelSelect -Old $oldEffortLabel -New $newEffortLabel -Marker 'const effortLabel = reasoning === void 0 ? void 0 : effectiveEffort === void 0 ? t("effort.providerDefault") : (reasoning.efforts.find'

$oldEffortOption = @'
				key: `effort:${effort.id}`,
				effort: effort.id,
				label: effort.name,
				...effort.description === void 0 ? {} : { description: effort.description }
'@
$newEffortOption = @'
				key: `effort:${effort.id}`,
				effort: effort.id,
				label: effortName(t, effort),
				...effort.description === void 0 ? {} : { description: effort.description }
'@
Apply-Replacement -Path $modelSelect -Old $oldEffortOption -New $newEffortOption -Marker 'label: effortName(t, effort),'

# ---------- 2. 斜杠命令描述 ----------
$commands = Join-Path $pkg 'dsh-client-ui-commands\lib\client.js'
$oldCmdImport = @'
		let _deepseek_ai_dsh_client_ui_primitives = require("@deepseek-ai/dsh-client-ui-primitives");
		//#region lib/types/client/directory.js
'@
$newCmdImport = @'
		let _deepseek_ai_dsh_client_ui_primitives = require("@deepseek-ai/dsh-client-ui-primitives");
