  retract_import: {
    /** DSH session id to retract (alternative to sourcePath; source file located via log marker / registry). */
    sessionId?: string;
    /** Source file path to retract (alternative to sessionId; directly removes the registry record by idempotency key). */
    sourcePath?: string;
  } & Record<string, JsonValue>;
  /** Read-only scan of the local default data roots for 17 external chat formats (Claude Code, Codex, Cursor, Gemini CLI, Reasonix, opencode, mimocode, zcode, Grok Build, OpenClaw, Pi, Hermes, Kimi CLI, Qoder CLI, ChatGPT exports, WorkBuddy, DSH session logs), returning a structured session index (format / sessionId / title / project / cwd / createdAt / lastActiveAt / messageCount / sourcePath / gitBranch / gitDirty / importStatus) to preview before batch import. path optional: when given, probes that root only (directory or single file); default scans all formats default roots. format optional: scan one format only (chatgpt has no auto root — point path at conversations.json; dsh default root is ~/.dsh/sessions). query optional: substring filter on title / project / path (case-insensitive). In-process 30s TTL cache: repeated scans of the same key within 30s hit the cache without re-reading sources. Persistent mtime/size bookmarks (scan-cache.json): unchanged files skip re-scanning across process restarts. Read-only: no DB writes, no create/append, no session or registry mutation. Returns { sessions, total }. */
  scan_discover: {
    /** Optional: scan root (directory or single file, e.g. ~/.claude/projects, a .jsonl, or conversations.json). Default scans all formats default roots. */
    path?: string;
    /** Optional: scan only this format; default probes all formats by path. */
    format?: "claude" | "codex" | "cursor" | "gemini" | "reasonix" | "opencode" | "mimocode" | "zcode" | "grokbuild" | "openclaw" | "pi" | "hermes" | "kimi" | "qoder" | "chatgpt" | "workbuddy" | "dsh";
    /** Optional: substring filter on title / project / path (case-insensitive). */
    query?: string;
  } & Record<string, JsonValue>;
  /** Send a message to a background subagent by its subagent id, continuing the same conversation. It becomes the subagent's next turn: if it is still working, the message waits until its current turn finishes, so it cannot redirect work already underway. This call returns no answer from the subagent — only confirmation that the message was delivered — so use it to give it more work. A failure means the message was NOT delivered. */
  send_message: {
    /** The subagent id returned when the background subagent was started. */
    subagent_id: string;
    /** The message to deliver to the subagent. */
    message: string;
  } & Record<string, JsonValue>;
  /** Load the full instructions for an available skill. Call this with the exact skill name from the session skill catalog before acting on a task that names or clearly matches that skill. */
  skill: {
    /** The exact skill name from the available skills list. */
    name: string;
  } & Record<string, JsonValue>;
  /** Delegate a self-contained task to a subagent (a separate agent that works in its own context) to offload focused, independent work — research, a scoped implementation, an analysis — so it does not consume this conversation's context. The subagent returns its result, not its intermediate steps. Give it a complete, standalone prompt: it does not see this conversation. This tool runs in the background by default, immediately returns a durable subagent id, and keeps the child conversation available for later turns. When that run settles, the runtime sends the parent a notice containing its outcome and any final assistant message; `send_message` starts a later turn in the same child conversation. Set `run_in_background: false` only when your next action depends on receiving the result. */
  subagent: {
    /** A short (3-5 word) description of the delegated task, for display. */
    description: string;
    /** The complete, self-contained task for the subagent. It does not share this conversation's context, so include everything it needs. */
    prompt: string;
    /** Whether to run in the background and return a durable subagent id immediately. Defaults to true. Set false to wait for the result when your next action depends on it. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Delegate a task to a subagent that inherits this conversation: a child agent seeded with all completed turns so far (it does not see the current in-flight turn). Use this when the subtask builds on this conversation's context — a follow-up analysis, a review, a continuation — without consuming this conversation's context for the work itself. You receive its result, not its intermediate steps. This tool runs in the background by default, immediately returns a durable subagent id, and keeps the child conversation available for later turns. When that run settles, the runtime sends the parent a notice containing its outcome and any final assistant message; `send_message` starts a later turn in the same child conversation. Set `run_in_background: false` only when your next action depends on receiving the result. */
  subagent_fork: {
    /** A short (3-5 word) description of the delegated task, for display. */
    description: string;
    /** The task for the subagent. It already sees this conversation's completed turns, so build on them freely and state only what is new. */
    prompt: string;
    /** Whether to run in the background and return a durable subagent id immediately. Defaults to true. Set false to wait for the result when your next action depends on it. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Write back new complete turns from a DSH session into its Claude Code JSONL source, so the changes are resumable in real Claude Code (--resume). Call this after continuing an imported conversation inside DSH, when you want the source transcript to catch up. target:"source" (default) writes back to the original imported file; target:"copy" writes back to a copy previously produced by export_chat format=claude (must be exported first). Guards never overwrite silently: sourceShrunk, source modified externally, tail uuid/watermark mismatch, and concurrent writer version mismatch are all skipped and reported; force:true skips the guards and re-anchors on the current file (watermark + tail). Only turn/end-closed complete turns are written (half-open in-progress turns are not, reported as incompleteFinalTurn); dryRun only computes, never writes. Returns status: synced | no-new-turns | skipped plus the writeback watermark. */
  sync_to_claude: {
