    sessionId: string;
    /** Optional: 'source' (default, the imported source file) | 'copy' (a copy from export_chat format=claude; must be exported first). */
    target?: string;
    /** Optional: true skips the guards and re-anchors on the current file (watermark + tail); may overwrite external edits; default false. */
    force?: boolean;
    /** Optional: true fully computes (incl. format precheck) without writing or updating the registry. */
    dryRun?: boolean;
  } & Record<string, JsonValue>;
  /** Record and update a structured task list for the current work. Send the ENTIRE list every call — it REPLACES the previous list (there are no partial updates, no per-item edits). Use it to plan multi-step work and show progress: add one todo per concrete step before you start. Mark every todo being actively worked on `in_progress` — several at once when work genuinely runs in parallel (e.g. concurrent subagents or background commands), one for sequential work; while work remains, at least one task should be `in_progress`. Mark a todo `completed` the moment it is done (do not batch completions), and allow no `in_progress` item only once all work is complete. Skip the list for trivial single-step tasks. Statuses: `pending` (not started), `in_progress` (being worked on now), `completed` (finished). */
  todo_write: {
    /** The COMPLETE task list, replacing any previous list. */
    todos: ({
      /** What the task is — a short imperative line. */
      content: string;
      /** pending (not started) | in_progress (now) | completed (done). */
      status: "pending" | "in_progress" | "completed";
    })[];
  } & Record<string, JsonValue>;
  /** Update the exact current goal revision. edit, pause, and resume require a direct top-level human request. During an automatic continuation of the current goal, complete and blocked are also allowed. blocked is rejected before the configured minimum round count; the model remains responsible for judging that the same condition persisted across those rounds and must explain it in blocked_reason. */
  update_goal: {
    /** Exact id returned by get_goal. */
    goal_id: string;
    /** Exact positive revision returned by get_goal. */
    revision: number;
    /** edit | pause | resume | complete | blocked */
    action: "edit" | "pause" | "resume" | "complete" | "blocked";
    /** Replacement objective; valid only with action edit. */
    objective?: string;
    /** Replacement cap; valid only with action edit. */
    max_goal_rounds?: number;
    /** Concrete blocking condition; required only with action blocked. */
    blocked_reason?: string;
  } & Record<string, JsonValue>;
  /** Read-only structural validation of an imported (or any) DSH session: event structure (seq continuity / type whitelist / surfaceOp / sourceEventSeqs pointing at tool/call), turn balance (turn/step pairing), and tool pairing (every tool/call has a tool/result and vice versa). Call this to diagnose a session that fails to resume or misbehaves. Zero side effects: list + readFrom only, never load/prepare or rewrite. Issues are reported per item (kind + seq + message, capped at 20); repairHints give per-kind fixes (re-import / close half-open turns / source transcript boundary notes); failures are loud. Returns { ok, problems, repairHints }. */
  verify_session: {
    /** DSH session id to validate (required). */
    sessionId: string;
