  /** 文字转语音：调用 edge-tts（微软 Edge 朗读服务，免费）合成 MP3。text 必填（≤5000 字符，更长请分段）；voice 可选（默认 zh-CN-XiaoxiaoNeural，清单见 voice_list）；rate/pitch 如 +10%、-2Hz；输出默认 voice_output.mp3（同名自动加序号）。 */
  voice_tts: {
    /** 要合成的文本（必填，≤5000 字符）。 */
    text: string;
    /** 音色 id（可选，默认配置的 ttsVoice）。 */
    voice?: string;
    /** 语速，如 +20% 或 -10%（可选）。 */
    rate?: string;
    /** 音调，如 +2Hz 或 -1Hz（可选）。 */
