  /** 检查 QQ 文游（<QQ_GROUP_NAME_001>/骰子/小）群自其游标以来的新增消息（必要时先解密 QQ 消息库，可能耗时 1~3 分钟）。参数 group 可选，缺省为主群；force=true 强制重新解密。 */
  wenyou_check: {
    /** 强制重新解密 QQ 数据库（默认 false，源文件未变化时复用已解密库） */
    force?: boolean;
